(function(){"use strict";var w=window.ScripturaJosephusWorks||(window.ScripturaJosephusWorks={});var a=w.guerra||(w.guerra={});a[6]={"work":"guerra","book":6,"title":"Φλαυίου Ἰωσήπου ἱστορία Ἰουδαϊκοῦ πολέμου πρὸς Ῥωμαίους βιβλίον [στιγμα].","chapters":{"1":[{"number":1,"text":"Τὰ μὲν οὖν τῶν Ἱεροσολύμων πάθη προύκοπτεν καθʼ ἡμέραν ἐπὶ τὸ χεῖρον τῶν τε στασιαστῶν μᾶλλον παροξυνομένων ἐν ταῖς συμφοραῖς καὶ τοῦ λιμοῦ μετὰ τὸν δῆμον ἤδη κἀκείνους νεμομένου."},{"number":2,"text":"τό γε μὴν πλῆθος τῶν σεσωρευμένων ἀνὰ τὴν πόλιν πτωμάτων ὄψει τε φρικῶδες ἦν καὶ λοιμώδη προσέβαλλεν ὀσμὴν πρός τε τὰς ἐκδρομὰς ἐμπόδιον τοῖς μαχομένοις· ὥσπερ γὰρ διὰ παρατάξεως φόνῳ μυρίῳ γεγυμνασμένης χωροῦντας ἔδει τὰ σώματα πατεῖν."},{"number":3,"text":"οἱ δʼ ἐπιβαίνοντες οὔτʼ ἔφριττον οὔτʼ ἠλέουν οὔτε κλῃδόνα κακὴν σφῶν αὐτῶν ὑπελάμβανον τὴν εἰς τοὺς κατοιχομένους ὕβριν,"},{"number":4,"text":"πεφυρμένοι δʼ ὁμοφύλῳ φόνῳ τὰς δεξιὰς ἐπὶ τὸν πρὸς τοὺς ἀλλοφύλους πόλεμον ἐξέθεον, ὀνειδίζοντες, ἔμοιγε δοκεῖν, τὸ θεῖον εἰς βραδυτῆτα τῆς ἐπʼ αὐτῶν κολάσεως· οὐ γὰρ ἐλπίδι νίκης ὁ πόλεμος, ἤδη δὲ ἀπογνώσει σωτηρίας ἐθρασύνετο."},{"number":5,"text":"Ῥωμαῖοι δὲ καίτοι πολλὰ περὶ τὴν τῆς ὕλης συγκομιδὴν ταλαιπωρούμενοι τὰ χώματα διήγειραν μιᾷ καὶ εἴκοσιν ἡμέραις, κείραντες, ὡς προείρηται, τὴν περὶ τὸ ἄστυ χώραν ἐπʼ ἐνενήκοντα σταδίους ἐν κύκλῳ πᾶσαν."},{"number":6,"text":"ἦν δʼ ἐλεεινὴ καὶ τῆς γῆς ἡ θέα· τὰ γὰρ πάλαι δένδρεσι καὶ παραδείσοις κεκοσμημένα τότε πανταχόθεν ἠρήμωτο καὶ περικέκοπτο τὴν ὕλην,"},{"number":7,"text":"οὐδείς τε τὴν πάλαι Ἰουδαίαν καὶ τὰ περικαλλῆ προάστεια τῆς πόλεως ἑωρακὼς ἀλλόφυλος, ἔπειτα τὴν τότε βλέπων ἐρημίαν οὐκ ὠλοφύρατο καὶ κατεστέναξεν τὴν μεταβολὴν παρʼ ὅσον γένοιτο·"},{"number":8,"text":"πάντα γὰρ ἐλυμήνατο τὰ σημεῖα τοῦ κάλλους ὁ πόλεμος, καὶ οὐκ ἄν τις ἐξαπίνης ἐπιστὰς τῶν προεγνωκότων ἐγνώρισε τὸν τόπον, ἀλλὰ παρὼν ἐζήτει τὴν πόλιν."},{"number":9,"text":"Ῥωμαίοις δὲ καὶ Ἰουδαίοις τὸ τέλος τῶν χωμάτων ἴσην ἐνεποίει δέους ἀρχήν·"},{"number":10,"text":"οἱ μὲν γάρ, εἰ μὴ καὶ ταῦτα καύσειαν, ἁλώσεσθαι τὴν πόλιν προσεδόκων, Ῥωμαῖοι δʼ οὐκ [ἂν] ἔθʼ αἱρήσειν κἀκείνων διαφθαρέντων."},{"number":11,"text":"ὕλης τε γὰρ ἦν ἀπορία, καὶ τῶν μὲν πόνων ἤδη τὸ σῶμα, τῶν δὲ ἐπαλλήλων πταισμάτων αἱ ψυχαὶ τοῖς στρατιώταις ἐλείποντο."},{"number":12,"text":"τάς γε μὴν κατὰ τὴν πόλιν συμφορὰς Ῥωμαίοις πλέον εἶναι συνέβαινε πρὸς ἀθυμίας ἢ τοῖς ἐν αὐτῇ· παρὰ γὰρ τὰ τηλικαῦτα πάθη τοῖς μαχομένοις οὐδὲν ἐχρῶντο μαλακωτέροις,"},{"number":13,"text":"ἀλλʼ ἐθραύοντο πάντοτε τὰς ἐλπίδας, τῶν μὲν χωμάτων ταῖς ἐπιβουλαῖς, τῶν δʼ ὀργάνων στερρότητι τοῦ τείχους, τῆς δὲ κατὰ χεῖρα μάχης ταῖς τῶν συμπλεκομένων τόλμαις πλεονεκτούμενοι, τὸ δὲ μέγιστον, στάσεώς τε καὶ λιμοῦ καὶ πολέμου καὶ τοσούτων κακῶν εὑρίσκοντες ἐπάνω τὸ παράστημα τῆς ψυχῆς Ἰουδαίους ἔχοντας."},{"number":14,"text":"ὑπελάμβανόν τε τῶν ἀνδρῶν ἀμάχους μὲν τὰς ὁρμάς, ἀνάλωτον δὲ τὴν ἐπὶ συμφοραῖς εὐθυμίαν εἶναι· τί γὰρ ἂν μὴ ὑποστῆναι δεξιᾷ τύχῃ χρωμένους τοὺς ὑπὸ κακῶν πρὸς ἀλκὴν τρεπομένους; οἱ μὲν οὖν ἐρρωμενεστέρας διὰ ταῦτα τῶν χωμάτων ἐποιοῦντο τὰς φυλακάς."},{"number":15,"text":"Οἱ δὲ περὶ τὸν Ἰωάννην κατὰ τὴν Ἀντωνίαν ἅμα καὶ πρὸς τὸ μέλλον, εἰ καταρριφθείη τὸ τεῖχος, ἠσφαλίζοντο καὶ πρὶν ἐπιστῆναι τοὺς κριοὺς ἐπέθεντο τοῖς ἔργοις."},{"number":16,"text":"οὐ μὴν ἐκράτησάν γε τῆς ἐπιχειρήσεως, ἀλλὰ προελθόντες μετὰ λαμπάδων πρὶν ἐγγίσαι τοῖς χώμασι ψυχρότεροι τῆς ἐλπίδος ὑπέστρεψαν."},{"number":17,"text":"πρῶτον μὲν γὰρ οὐδʼ ὁμονοεῖν ἡ σκέψις αὐτῶν ἐῴκει κατὰ μέρος ἐκπηδώντων κἀκ διαλειμμάτων καὶ μεμελλημένως μετὰ δέους καθόλου τε εἰπεῖν οὐκ Ἰουδαϊκῶς· τὰ γὰρ ἴδια τοῦ ἔθνους ὑστέρητο ἅμα ἡ τόλμα καὶ ὁρμὴ καὶ δρόμος ὁμοῦ πάντων καὶ τὸ μηδὲ πταίοντας ἀναστρέφειν."},{"number":18,"text":"ἀτονώτεροι δʼ ἑαυτῶν προελθόντες καὶ τοὺς Ῥωμαίους εὗρον ἐρρωμενέστερον τοῦ συνήθους παρατεταγμένους·"},{"number":19,"text":"τοῖς μέν γε σώμασι καὶ ταῖς πανοπλίαις οὕτως ἐφράξαντο τὰ χώματα πάντοθεν ὡς τῷ πυρὶ μηδαμόθεν καταλιπεῖν παράδυσιν, τὴν δὲ ψυχὴν ἐτόνωσαν ἕκαστος μὴ μετακινηθῆναι τῆς τάξεως πρὸ θανάτου."},{"number":20,"text":"πρὸς γὰρ τῷ πάσας αὐτῶν ὑποκόπτεσθαι τὰς ἐλπίδας, εἰ κἀκεῖνα καταφλεγείη τὰ ἔργα, δεινὴ τοὺς στρατιώτας εἶχεν αἰδώς, εἰ πάντα κρατήσειαν πανουργία μὲν ἀρετῆς, ἀπόνοια δʼ ὅπλων, πλῆθος δʼ ἐμπειρίας, Ἰουδαῖοι δὲ Ῥωμαίων."},{"number":21,"text":"ἅμα δὲ τἀφετήρια συνήργει τῶν προπηδώντων ἐφικνούμενα, καὶ πεσών τις τῷ μεθʼ αὑτὸν ἐμπόδιον ἦν, ὅ τε κίνδυνος τοῦ πρόσω χωρεῖν ἐποίει μαλακωτέρους."},{"number":22,"text":"τῶν δʼ ἐνδοτέρω βέλους ὑποδραμόντων οἱ μὲν πρὶν εἰς χεῖρας ἐλθεῖν τὴν εὐταξίαν καὶ τὸ πύκνωμα τῶν πολεμίων καταπλαγέντες, οἱ δὲ νυττόμενοι τοῖς ξυστοῖς ἐπαλινδρόμουν· καὶ τέλος ἀλλήλους κακίζοντες εἰς δειλίαν ἀνεχώρουν ἄπρακτοι. νουμηνίᾳ Πανέμου μηνὸς ἡ ἐπιχείρησις ἦν."},{"number":23,"text":"ἀναχωρησάντων δὲ τῶν Ἰουδαίων προσῆγον οἱ Ῥωμαῖοι τὰς ἑλεπόλεις, βαλλόμενοι πέτραις τε ἀπὸ τῆς Ἀντωνίας καὶ πυρὶ καὶ σιδήρῳ καὶ παντὶ τῷ χορηγουμένῳ Ἰουδαίοις ὑπὸ τῆς ἀνάγκης βέλει·"},{"number":24,"text":"καίπερ γὰρ πολὺ τῷ τείχει πεποιθότες καὶ τῶν ὀργάνων καταφρονοῦντες ὅμως ἐκώλυον τοὺς Ῥωμαίους προσάγειν."},{"number":25,"text":"οἱ δὲ τὴν σπουδὴν τῶν Ἰουδαίων τοῦ μὴ πληγῆναι τὴν Ἀντωνίαν ὑπολαμβάνοντες γίνεσθαι διʼ ἀσθένειαν τοῦ τείχους καὶ σαθροὺς ἐλπίσαντες εἶναι τοὺς θεμελίους ἀντεφιλονείκουν."},{"number":26,"text":"οὐ μὴν ὑπήκουε τὸ τυπτόμενον, ἀλλʼ οἱ μὲν συνεχῶς βαλλόμενοι καὶ πρὸς μηδένα τῶν καθύπερθεν κινδύνων ἐνδιδόντες ἐνεργοὺς παρεῖχον τὰς ἑλεπόλεις·"},{"number":27,"text":"ὡς δʼ ἦσαν ἐλάττους καὶ περιεθραύοντο ταῖς πέτραις, ἕτεροι τοὺς θυρεοὺς ὀροφώσαντες ὑπὲρ τῶν σωμάτων χερσὶ καὶ μοχλοῖς ὑπώρυττον τοὺς θεμελίους, καὶ τέσσαράς γε λίθους προσκαρτερήσαντες ἐξέσεισαν."},{"number":28,"text":"ἀνέπαυσε δὲ νὺξ ἑκατέρους, κἀν ταύτῃ τὸ τεῖχος ὑπὸ τῶν κριῶν σεσαλευμένον, καὶ καθʼ ὃ τοῖς προτέροις ἐπιβουλεύων χώμασιν ὁ Ἰωάννης ὑπώρυξεν ἐνδούσης τῆς διώρυχος, ἐξαπίνης κατερείπεται."},{"number":29,"text":"Τούτου συμβάντος παραδόξως ἑκατέροις διετέθη τὰ φρονήματα·"},{"number":30,"text":"Ἰουδαίους μὲν γάρ, οὓς ἀθυμεῖν εἰκὸς ἦν, τῷ μὴ παρʼ ἐλπίδα γενέσθαι τὸ πτῶμα καὶ προησφαλίσθαι πρὸς αὐτὸ θαρρεῖν ὡς μενούσης συνέβαινε τῆς Ἀντωνίας·"},{"number":31,"text":"Ῥωμαίων δέ γε τὴν παρʼ ἐλπίδα χαρὰν ἐπὶ τῷ καταρριφθέντι ταχέως ἔσβεσεν ὄψις ἑτέρου τείχους, ὅπερ ἔνδοθεν οἱ περὶ τὸν Ἰωάννην ἀντῳκοδομήκεσαν."},{"number":32,"text":"εὐμαρεστέρα γε μὴν τῆς πρότερον ἡ προσβολὴ κατεφαίνετο· τό τε γὰρ ἀναβῆναι διὰ τῶν καταρριφθέντων ῥᾷον ἐδόκει, καὶ τὸ τεῖχος ἀσθενέστερόν τε πολλῷ τῆς Ἀντωνίας καὶ ταχέως τῷ πρόσκαιρον εἶναι λύειν ὑπελάμβανον. οὐ μὴν ἐτόλμα τις ἀναβῆναι· προῦπτος γὰρ τοῖς ἀρξαμένοις ἦν ἀπώλεια."},{"number":33,"text":"Νομίζων δὲ ὁ Τίτος ἐγείρεσθαι μάλιστα τὰς τῶν πολεμούντων προθυμίας ἐλπίδι καὶ λόγῳ, τάς τε προτροπὰς καὶ τὰς ὑποσχέσεις πολλάκις μὲν λήθην ἐνεργάζεσθαι τῶν κινδύνων, ἔστι δʼ ὅτε καὶ θανάτου καταφρόνησιν, συναγαγὼν ἐπὶ ταὐτὸ τοὺς ἀλκίμους ἐπειρᾶτο τῶν ἀνδρῶν,"},{"number":34,"text":"ὦ συστρατιῶται, λέγων, τὸ μὲν παρακελεύειν ἐπὶ τὰ μὴ φέροντα κίνδυνον αὐτόθεν τοῖς παρακελευομένοις ἀκλεές, ἀμέλει δὲ καὶ τῷ παρακελεύοντι φέρει κατάγνωσιν ἀνανδρίας."},{"number":35,"text":"δεῖ δέ, οἶμαι, προτροπῆς εἰς μόνα τὰ σφαλερὰ τῶν πραγμάτων, ὡς ἐκεῖνά γε καθʼ αὑτοὺς πράττειν ἄξιον."},{"number":36,"text":"ὥστʼ ἔγωγε τὸ μὲν ὑπάρχειν χαλεπὴν τὴν ἐπὶ τὸ τεῖχος ἄνοδον αὐτὸς ὑμῖν προτίθημι· τὸ δʼ ὅτι μάλιστα προσήκει μάχεσθαι τοῖς δυσκόλοις τοὺς ἀρετῆς ἐφιεμένους καὶ ὅτι καλὸν ἐν εὐκλείᾳ τελευτὴ καὶ ὡς οὐκ ἄκαρπον ἔσται τοῖς καταρξαμένοις τὸ γενναῖον, διέξειμι."},{"number":37,"text":"πρῶτον μὲν οὖν ὑμῶν γενέσθω προτροπὴ τό τινας ἴσως ἀποτρέπον, ἡ Ἰουδαίων μακροθυμία καὶ τὸ καρτερικὸν ἐν οἷς κακοπαθοῦσιν·"},{"number":38,"text":"αἰσχρὸν γὰρ Ῥωμαίους τε ὄντας καὶ στρατιώτας ἐμούς, καὶ διδακτὸν μὲν ἐν εἰρήνῃ τὸ πολεμεῖν, ἔθιμον δὲ ἐν πολέμῳ τὸ κρατεῖν ἔχοντας, ἡττᾶσθαι κατὰ χεῖρα Ἰουδαίων ἢ κατὰ ψυχήν, καὶ ταῦτα πρὸς τῷ τέλει τῆς νίκης καὶ συνεργουμένους ὑπὸ τοῦ θεοῦ."},{"number":39,"text":"τὰ γὰρ ἡμέτερα πταίσματα τῆς Ἰουδαίων ἐστὶν ἀπονοίας, τὰ δʼ ἐκείνων πάθη ταῖς τε ὑμετέραις ἀρεταῖς καὶ ταῖς τοῦ θεοῦ συνεργίαις αὔξεται·"},{"number":40,"text":"στάσις γὰρ καὶ λιμὸς καὶ πολιορκία καὶ δίχα μηχανημάτων πίπτοντα τείχη τί ἂν ἀλλʼ ἢ θεοῦ μὲν εἴη μῆνις ἐκείνοις, βοήθεια δὲ ἡμετέρα;"},{"number":41,"text":"τὸ τοίνυν μὴ μόνον ἐλαττοῦσθαι χειρόνων, ἀλλὰ καὶ τὴν θείαν συμμαχίαν προδιδόναι πρὸς ἡμῶν οὐκ ἂν εἴη."},{"number":42,"text":"πῶς δʼ οὐκ αἰσχρὸν Ἰουδαίους μέν, οἷς οὐ πολλὴν αἰσχύνην φέρει τὸ λείπεσθαι μαθοῦσι δουλεύειν, ὑπὲρ τοῦ μηκέτι τοῦτο πάσχειν θανάτου καταφρονεῖν καὶ πολλάκις εἰς μέσους ἡμᾶς ἐκτρέχειν, οὐκ ἐλπίδι τοῦ κρατήσειν ἀλλὰ διὰ ψιλὴν ἐπίδειξιν ἀνδρείας·"},{"number":43,"text":"ὑμᾶς δὲ τοὺς γῆς ὀλίγου δεῖν ἁπάσης καὶ θαλάσσης κρατοῦντας, οἷς καὶ τὸ μὴ νικᾶν ὄνειδος, μηδʼ ἅπαξ εἰς τοὺς πολεμίους παραβάλλεσθαι,"},{"number":44,"text":"περιμένειν δὲ τὸν λιμὸν κατʼ αὐτῶν καὶ τὴν τύχην ἀργοὺς καθεζομένους μετὰ τοιούτων ὅπλων, καὶ ταῦτα διʼ ὀλίγου τοῦ παραβόλου τὸ πᾶν κατορθῶσαι δυναμένους;"},{"number":45,"text":"ἀναβάντες γοῦν ἐπὶ τὴν Ἀντωνίαν ἔχομεν τὴν πόλιν· καὶ γὰρ ἂν γίνηταί τις ἔτι πρὸς τοὺς ἔνδον, ὅπερ οὐκ οἶμαι, μάχη, τό γε κατὰ κορυφὴν εἶναι καὶ ταῖς ἀναπνοαῖς ἐπικαθῆσθαι τῶν πολεμίων ταχέως τὴν ὁλοσχερῆ νίκην ἐγγυᾶται."},{"number":46,"text":"καὶ ἔγωγε τὸ μὲν ὑμνεῖν ἄρτι τὴν ἐν πολέμῳ τελευτὴν καὶ τὴν ἐπὶ τοῖς ἀρειμανίοις πεσοῦσιν ἀθανασίαν παραλιπὼν ἐπαρασαίμην ἂν τοῖς ἄλλως ἔχουσι τὸν κατʼ εἰρήνην ἐκ νόσου θάνατον, οἷς μετὰ τοῦ σώματος καὶ ἡ ψυχὴ τάφῳ κατακρίνεται."},{"number":47,"text":"τίς γὰρ οὐκ οἶδε τῶν ἀγαθῶν ἀνδρῶν ὅτι τὰς μὲν ἐν παρατάξει ψυχὰς σιδήρῳ τῶν σαρκῶν ἀπολυθείσας τὸ καθαρώτατον στοιχεῖον αἰθὴρ ξενοδοχῶν ἄστροις ἐγκαθιδρύει, δαίμονες δʼ ἀγαθοὶ καὶ ἥρωες εὐμενεῖς ἰδίοις ἐγγόνοις ἐμφανίζονται, τὰς δὲ ἐν νοσοῦσι τοῖς σώμασι συντακείσας,"},{"number":48,"text":"κἂν τὰ μάλιστα κηλίδων ἢ μιασμάτων ὦσι καθαραί, νὺξ ὑπόγειος ἀφανίζει καὶ λήθη βαθεῖα δέχεται, λαμβανούσας ἅμα τοῦ τε βίου καὶ τῶν σωμάτων ἔτι δὲ τῆς μνήμης περιγραφήν;"},{"number":49,"text":"εἰ δὲ κέκλωσται μὲν ἀνθρώποις ἀναγκαία τελευτή, κουφότερον δὲ εἰς αὐτὴν νόσου πάσης σίδηρος ὑπηρέτης, πῶς οὐκ ἀγεννὲς μὴ διδόναι ταῖς χρείαις ὃ τῷ χρεὼν ἀποδώσομεν;"},{"number":50,"text":"καὶ ταῦτα μὲν ὡς οὐ δυναμένων σωθῆναι τῶν ἐπιχειρησόντων διεξῆλθον· ἔνεστι δὲ σώζεσθαι τοῖς ἀνδριζομένοις κἀκ τῶν σφαλερωτάτων."},{"number":51,"text":"πρῶτον μὲν γὰρ τὸ καταρριφθὲν εὐεπίβατον, ἔπειτα πᾶν τὸ οἰκοδομηθὲν εὐδιάλυτον, ὑμεῖς τε πλείους θαρσήσαντες ἐπὶ τὴν πρᾶξιν ἀλλήλοις προτροπὴ καὶ βοήθεια γίνεσθε, καὶ τοῖς πολεμίοις τὸ ὑμέτερον παράστημα ταχέως κλάσει τὰ φρονήματα."},{"number":52,"text":"καὶ τάχα ἂν ὑμῖν ἀναίμακτον τὸ κατόρθωμα γένοιτο μόνον καταρξαμένοις· ἀναβαίνοντας μὲν γὰρ κωλύειν πειράσονται κατὰ τὸ εἰκός, λαθόντας δὲ καὶ βιασαμένους ἅπαξ οὐκ ἂν ὑποσταῖεν ἔτι, κἂν ὀλίγοι φθάσητε."},{"number":53,"text":"τὸν δὲ καταρξάμενον αἰσχυνοίμην ἂν εἰ μὴ ποιήσαιμι ζηλωτὸν ἐν ταῖς ἐπικαρπίαις, καὶ ὁ μὲν ζῶν ἄρξει τῶν νῦν ὁμοίων, μακαριστὰ δʼ ἀκολουθήσει καὶ τοῖς πεσοῦσι τὰ ἀριστεῖα."},{"number":54,"text":"Τοιαῦτα τοῦ Τίτου διεξιόντος τὸ μὲν ἄλλο πλῆθος ἔδεισε τοῦ κινδύνου τὸ μέγεθος, τῶν δʼ ἐν ταῖς σπείραις στρατευομένων Σαβῖνος τοὔνομα, γένος ἀπὸ Συρίας, ἀνὴρ καὶ κατὰ χεῖρα καὶ κατὰ ψυχὴν ἄριστος ἐφάνη."},{"number":55,"text":"καίτοι προϊδὼν ἄν τις αὐτὸν ἀπό γε τῆς σωματικῆς ἕξεως οὐδʼ εἰκαῖον εἶναι στρατιώτην ἔδοξε· μέλας μὲν γὰρ ἦν τὴν χροίαν, ἰσχνός, τὴν σάρκα πεπιλημένος, ἀλλʼ ἐνῴκει τις ἡρωικὴ ψυχὴ λεπτῷ σώματι καὶ πολὺ τῆς ἰδίας ἀλκῆς στενοτέρῳ."},{"number":56,"text":"πρῶτος γοῦν ἀναστάς ἐπιδίδωμί σοι, Καῖσαρ, ἔφη, προθύμως ἐμαυτόν."},{"number":57,"text":"πρῶτος ἀναβαίνω τὸ τεῖχος. καὶ εὔχομαι μέν μου τῇ τε ἰσχύι καὶ τῇ γνώμῃ τὴν σὴν ἀκολουθῆσαι τύχην, εἰ δὲ νεμεσηθείην τῆς ἐπιβολῆς, ἴσθι μή με πταίσαντα παρʼ ἐλπίδας, ἀλλʼ ὑπὲρ σοῦ κρίσει τὸν θάνατον ᾑρημένον."},{"number":58,"text":"ταῦτα εἰπὼν καὶ τῇ μὲν ἀριστερᾷ χειρὶ τὸν θυρεὸν ὑπὲρ τῆς κεφαλῆς ἀνατείνας, τῇ δεξιᾷ δὲ τὸ ξίφος σπασάμενος ἐχώρει πρὸς τὸ τεῖχος περὶ ὥραν μάλιστα τῆς ἡμέρας ἕκτην."},{"number":59,"text":"εἵποντο δʼ αὐτῷ καὶ τῶν ἄλλων ἕνδεκα μόνοι ζηλωταὶ τῆς ἀνδρείας γενόμενοι· προῆγε δὲ πολὺ πάντων ὁ ἀνὴρ ὁρμῇ τινι δαιμονίῳ χρώμενος."},{"number":60,"text":"οἱ φρουροὶ δὲ ἀπὸ τοῦ τείχους κατηκόντιζόν τε αὐτοὺς καὶ βέλεσι πάντοθεν ἀπείροις ἔβαλλον καὶ πέτρας ἐξαισίους κατεκύλιον,"},{"number":61,"text":"αἳ ἐκ τῶν μὲν ἕνδεκα παρέσυραν ἐνίους, ὁ δὲ Σαβῖνος ἀπαντῶν τοῖς ἀφιεμένοις καὶ καταχωννύμενος ὑπὸ τῶν βελῶν οὐ πρότερον ἐπέσχε τὴν ὁρμὴν ἢ γενέσθαι τε ἐπʼ ἄκρῳ καὶ τρέψασθαι τοὺς πολεμίους·"},{"number":62,"text":"καταπλαγέντες γὰρ αὐτοῦ τήν τε δύναμιν οἱ Ἰουδαῖοι καὶ τὸ παράστημα τῆς ψυχῆς, ἅμα δὲ καὶ πλείους ἀναβεβηκέναι δόξαντες ἐτράπησαν."},{"number":63,"text":"ἔνθα δὴ καταμέμψαιτʼ ἄν τις ὡς φθονερὰν ἐπὶ ταῖς ἀρεταῖς τὴν τύχην καὶ κωλύουσαν ἀεὶ τὰ παράδοξα τῶν κατορθωμάτων."},{"number":64,"text":"ὁ γοῦν ἀνὴρ οὗτος ὅτʼ ἐκράτησε τῆς ἐπιβολῆς, ἐσφάλη καὶ πταίσας πρός τινι πέτρᾳ πρηνὴς ἐπʼ αὐτὴν μετὰ μεγίστου ψόφου κατέπεσεν· ἐπιστραφέντες δὲ οἱ Ἰουδαῖοι καὶ κατιδόντες μόνον τε αὐτὸν καὶ πεπτωκότα, πάντοθεν ἔβαλλον."},{"number":65,"text":"ὁ δʼ ἐς γόνυ διαναστὰς καὶ προκαλυψάμενος τὸν θυρεὸν τὸ μὲν πρῶτον ἠμύνετο καὶ πολλοὺς τῶν πλησιασάντων ἔτρωσεν·"},{"number":66,"text":"αὖθις δʼ ὑπὸ πλήθους τραυμάτων παρῆκε τὴν δεξιὰν καὶ τέλος πρὶν ἀποδοῦναι τὴν ψυχὴν κατεχώσθη τοῖς βέλεσιν, ἀνὴρ ἄξιος μὲν ἀμείνονι χρῆσθαι διʼ ἀνδρείαν καὶ τύχῃ, πεσὼν δὲ τῆς ἐπιβολῆς ἀναλόγως."},{"number":67,"text":"τῶν δὲ ἄλλων τρεῖς μὲν τοὺς ἤδη πρὸς τοῖς ἄκροις ὄντας συντρίψαντες ἀπέκτειναν τοῖς λίθοις, οἱ δὲ ὀκτὼ τραυματίαι κατασυρέντες ἀνεκομίσθησαν εἰς τὸ στρατόπεδον. ταῦτα μὲν οὖν τρίτῃ μηνὸς Πανέμου ἐπράχθη."},{"number":68,"text":"Μετὰ δʼ ἡμέρας δύο τῶν προκοιτούντων τινὲς ἐπὶ τοῖς χώμασι φυλάκων εἴκοσι συνελθόντες προσποιοῦνται μὲν τὸν τοῦ πέμπτου τάγματος σημαιαφόρον καὶ δύο τινὰς τῶν ἐν ταῖς ἴλαις ἱππέων καὶ σαλπικτὴν ἕνα, κατὰ δὲ ὥραν τῆς νυκτὸς ἐνάτην προσβαίνουσι μὲν ἡσυχῆ διὰ τῶν ἐρειπίων ἐπὶ τὴν Ἀντωνίαν, ἀποσφάξαντες δὲ τοὺς πρώτους τῶν φρουρῶν κοιμωμένους κρατοῦσι τοῦ τείχους καὶ τῷ σαλπικτῇ σημαίνειν ἐκέλευσαν."},{"number":69,"text":"πρὸς ὃ τῶν μὲν ἄλλων φυλάκων ἐξανάστασις αἰφνίδιος ἦν καὶ φυγὴ πρίν τινα τὸ πλῆθος ἐπιδεῖν τῶν ἐπιβεβηκότων· ὅ τε γὰρ φόβος καὶ ἡ σάλπιγξ φαντασίαν αὐτοῖς τοῦ πλῆθος ἀναβεβηκέναι πολεμίων παρεῖχε."},{"number":70,"text":"Καῖσαρ δὲ τοῦ σημείου κατακούσας ἐξοπλίζει τήν τε δύναμιν διὰ τάχους καὶ μετὰ τῶν ἡγεμόνων πρῶτος ἀναβαίνει τοὺς ἐπιλέκτους ἔχων."},{"number":71,"text":"καταπεφευγότων δὲ Ἰουδαίων εἰς τὸ ἱερὸν καὶ αὐτοὶ διὰ τῆς διώρυγος εἰσέπιπτον, ἣν ὁ Ἰωάννης ἐπὶ τὰ χώματα τῶν Ῥωμαίων ὑπώρυξε."},{"number":72,"text":"καὶ διαστάντες ἀπʼ ἀμφοτέρων οἱ στασιασταὶ τῶν ταγμάτων, τοῦ τε Ἰωάννου καὶ τοῦ Σίμωνος, εἶργον αὐτοὺς οὐδεμίαν οὔτε ἰσχύος οὔτε προθυμίας ἐλλείποντες ὑπερβολήν·"},{"number":73,"text":"πέρας γὰρ ἁλώσεως ὑπελάμβανον τὸ Ῥωμαίους παρελθεῖν εἰς τὸ ἅγιον, ὃ δὴ κἀκεῖνοι τοῦ κρατεῖν ἀρχήν."},{"number":74,"text":"συρρήγνυται δὲ περὶ τὰς εἰσόδους μάχη καρτερά, τῶν μὲν καταλαβέσθαι καὶ τὸ ἱερὸν εἰσβιαζομένων, τῶν δὲ Ἰουδαίων ἐξωθούντων αὐτοὺς ἐπὶ τὴν Ἀντωνίαν."},{"number":75,"text":"καὶ τὰ βέλη μὲν ἦν ἀμφοτέροις ἄχρηστα καὶ τὰ δόρατα, σπασάμενοι δὲ τὰ ξίφη συνεπλέκοντο, καὶ περὶ τὴν συμβολὴν ἄκριτον ἦν ὁποτέρωθεν ἕκαστοι μάχοιντο, πεφυρμένων μὲν τῶν ἀνδρῶν καὶ περὶ τὴν στενοχωρίαν διηλλαγμένων, τῆς δὲ βοῆς ἀσημάντου προσπιπτούσης διὰ τὸ μέγεθος."},{"number":76,"text":"φόνος τε ἦν ἑκατέρωθεν πολύς, καὶ τῶν πεσόντων τά τε σώματα καὶ τὰς πανοπλίας πατοῦντες ἔθραυον οἱ μαχόμενοι."},{"number":77,"text":"ἀεὶ δʼ ἐφʼ ὁπότερον βρίσειεν ῥέων ὁ πόλεμος, παρακέλευσις μὲν ἦν τῶν πλεονεκτούντων, οἰμωγαὶ δὲ τῶν τρεπομένων. οὔτε δὲ αἱ φυγαὶ τόπον εἶχον οὔτε αἱ διώξεις, ἀλλʼ ἀγχώμαλοι ῥοπαὶ καὶ μετακλίσεις μεμιγμένης ἐγίνοντο τῆς παρατάξεως."},{"number":78,"text":"τοῖς δʼ ἔμπροσθεν γινομένοις ἢ τοῦ θνήσκειν ἢ τοῦ κτείνειν ἀνάγκη παρῆν οὐκ οὔσης ἀναφυγῆς· οἱ γὰρ κατὰ νώτου πρόσω βιαζόμενοι τοὺς σφετέρους παρʼ ἀμφοῖν οὐδὲ τῇ μάχῃ μεταίχμιον κατέλειπον."},{"number":79,"text":"πλεονεκτούντων δὲ τῶν Ἰουδαίων τοῖς θυμοῖς τὴν Ῥωμαίων ἐμπειρίαν καὶ κλινομένης καθάπαν ἤδη τῆς παρατάξεως, ἀπὸ γὰρ ἐνάτης ὥρας τῆς νυκτὸς εἰς ἑβδόμην τῆς ἡμέρας ἐπολέμουν,"},{"number":80,"text":"οἱ μὲν ἀθρόοι καὶ τὸν τῆς ἁλώσεως κίνδυνον ἔχοντες ἀνδρείας ἐφόδιον Ῥωμαῖοι δὲ μέρει τῆς δυνάμεως, οὔπω γὰρ ἐπαναβεβήκει τὰ τάγματα, κἀκείνοις ἐπανεῖχον οἱ μαχόμενοι τότε, κρατεῖν τῆς Ἀντωνίας ἀποχρῆν ἐπὶ τοῦ παρόντος ἐδόκει."},{"number":81,"text":"Ἰουλιανὸς δέ τις ἑκατοντάρχης τῶν ἀπὸ τῆς Βιθυνίας, οὐκ ἄσημος ὢν ἀνήρ, ὧν ἐγὼ κατʼ ἐκεῖνον ἱστόρησα τὸν πόλεμον ὅπλων τε ἐμπειρίᾳ καὶ ἀλκῇ σώματος καὶ ψυχῆς παραστήματι πάντων ἄριστος,"},{"number":82,"text":"ὁρῶν τοὺς Ῥωμαίους ἐνδιδόντας ἤδη καὶ κακῶς ἀμυνομένους, παρειστήκει δὲ Τίτῳ κατὰ τὴν Ἀντωνίαν, προπηδᾷ καὶ νικῶντας ἤδη τοὺς Ἰουδαίους τρέπεται μόνος μέχρι τῆς τοῦ ἐνδοτέρω ἱεροῦ γωνίας. ἔφευγε δὲ τὸ πλῆθος ἄθρουν, οὔτε τὴν ἰσχὺν οὔτε τὴν τόλμαν ἀνθρωπίνην ὑπολαμβάνοντες."},{"number":83,"text":"ὁ δὲ διὰ μέσων τῶν σκεδαννυμένων ἄλλοτε ἄλλῃ διᾴττων ἐφόνευε τοὺς καταλαμβανομένους, καὶ τῆς ὄψεως ἐκείνης οὐδὲν οὔτε τῷ Καίσαρι θαυμασιώτερον οὔτε τοῖς ἄλλοις παρέστη φρικωδέστερον."},{"number":84,"text":"ἐδιώκετο δὲ ἄρα καὶ αὐτὸς ὑπὸ τῆς εἱμαρμένης, ἣν ἀμήχανον διαφυγεῖν θνητὸν ὄντα."},{"number":85,"text":"τὰ γὰρ ὑποδήματα πεπαρμένα πυκνοῖς καὶ ὀξέσιν ἥλοις ἔχων, ὥσπερ τῶν ἄλλων στρατιωτῶν ἕκαστος, καὶ κατὰ λιθοστρώτου τρέχων ὑπολισθάνει, πεσὼν δὲ ὕπτιος μετὰ μεγίστου τῆς πανοπλίας ἤχου τοὺς φεύγοντας ἐπιστρέφει."},{"number":86,"text":"καὶ τῶν μὲν ἀπὸ τῆς Ἀντωνίας Ῥωμαίων ἤρθη βοὴ περὶ τἀνδρὶ δεισάντων, οἱ δὲ Ἰουδαῖοι περιστάντες αὐτὸν ἀθρόοι τοῖς τε ξυστοῖς καὶ ταῖς ῥομφαίαις πάντοθεν ἔπαιον."},{"number":87,"text":"ὁ δὲ πολὺν μὲν τῷ θυρεῷ σίδηρον ἐξεδέχετο, πολλάκις δὲ ἀναστῆναι πειράσας ὑπὸ τοῦ πλήθους τῶν τυπτόντων ἀνετράπη, καὶ κείμενος δʼ ὅμως ἔνυττε τῷ ξίφει πολλούς·"},{"number":88,"text":"οὐδὲ γὰρ ἀνῃρέθη ταχέως τῷ τε κράνει καὶ τῷ θώρακι πεφραγμένος πάντα τὰ καίρια πρὸς σφαγὴν καὶ τὸν αὐχένα συνέλκων· μέχρι κοπτομένων αὐτῷ τῶν ἄλλων μελῶν καὶ μηδενὸς προσαμῦναι τολμῶντος ἐνέδωκε."},{"number":89,"text":"δεινὸν δὲ πάθος εἰσῄει Καίσαρα ἀνδρὸς οὕτως ἐναρέτου καὶ ἐν ὄψει τοσούτων φονευομένου· καὶ αὐτὸν μὲν ὁ τόπος διέκλειε βοηθεῖν θέλοντα, τοὺς δυναμένους δὲ κατάπληξις."},{"number":90,"text":"Ἰουλιανὸς μὲν οὖν πολλὰ δυσθανατήσας καὶ τῶν κτεινόντων ὀλίγους ἀπλῆγας καταλιπὼν μόλις ἀποσφάττεται, μέγιστον οὐ παρὰ Ῥωμαίοις καὶ Καίσαρι μόνον ἀλλὰ καὶ παρὰ τοῖς πολεμίοις κλέος καταλιπών·"},{"number":91,"text":"Ἰουδαῖοι δὲ καὶ τὸν νεκρὸν ἁρπασάμενοι πάλιν τοὺς Ῥωμαίους τρέπονται καὶ κατακλείουσιν εἰς τὴν Ἀντωνίαν."},{"number":92,"text":"ἠγωνίσαντο δὲ ἐξ αὐτῶν ἐπισήμως κατὰ ταύτην τὴν μάχην Ἀλεξᾶς μέν τις καὶ Γυφθέος τοῦ Ἰωάννου τάγματος, ἐκ δὲ τῶν περὶ Σίμωνα Μαλαχίας τε καὶ ὁ τοῦ Μέρτωνος Ἰούδας, καὶ Σωσᾶ υἱὸς Ἰάκωβος τῶν Ἰδουμαίων ἡγεμών, τῶν δὲ ζηλωτῶν ἀδελφοὶ δύο, παῖδες Ἀρί, Σίμων τε καὶ Ἰούδης."}],"2":[{"number":93,"text":"Τίτος δὲ τοῖς μὲν σὺν αὐτῷ στρατιώταις κατασκάπτειν προσέταξε τοὺς θεμελίους τῆς Ἀντωνίας καὶ τῇ δυνάμει πάσῃ ῥᾳδίαν τὴν ἄνοδον εὐτρεπίζειν,"},{"number":94,"text":"αὐτὸς δὲ τὸν Ἰώσηπον παραστησάμενος· ἐπέπυστο γὰρ ἐπʼ ἐκείνης τῆς ἡμέρας, Πανέμου δʼ ἦν ἑπτακαιδεκάτη, τὸν ἐνδελεχισμὸν καλούμενον ἀνδρῶν ἀπορίᾳ διαλελοιπέναι τῷ θεῷ καὶ τὸν δῆμον ἐπὶ τούτῳ δεινῶς ἀθυμεῖν·"},{"number":95,"text":"λέγειν τῷ Ἰωάννῃ πάλιν ἐκέλευσεν ἃ καὶ πρότερον, ὡς εἰ καί τις αὐτὸν ἔρως κακὸς ἔχοι τοῦ μάχεσθαι, προελθόντι μεθʼ ὅσων βούλεται πολεμεῖν ἐξείη δίχα τοῦ συναπολέσθαι τήν τε πόλιν καὶ τὸν ναὸν αὐτῷ, μηκέτι μέντοι μιαίνειν τὸ ἅγιον μηδὲ εἰς τὸν θεὸν πλημμελεῖν, παρεῖναι δʼ αὐτῷ τὰς ἐπιλελοιπυίας θυσίας ἐκτελεῖν διʼ ὧν ἂν ἐπιλέξηται Ἰουδαίων."},{"number":96,"text":"καὶ ὁ Ἰώσηπος, ὡς ἂν εἴη μὴ τῷ Ἰωάννῃ μόνον ἀλλὰ καὶ τοῖς πολλοῖς ἐν ἐπηκόῳ, τά τε τοῦ Καίσαρος διήγγελλεν ἑβραΐζων,"},{"number":97,"text":"καὶ πολλὰ προσηντιβόλει φείσασθαι τῆς πατρίδος καὶ διασκεδάσαι τοῦ ναοῦ γευόμενον ἤδη τὸ πῦρ, τούς τʼ ἐναγισμοὺς ἀποδοῦναι τῷ θεῷ."},{"number":98,"text":"πρὸς ταῦτα τοῦ δήμου μὲν ἦν κατήφεια καὶ σιγή, πολλὰ δʼ ὁ τύραννος λοιδορηθείς τε τῷ Ἰωσήπῳ καὶ καταρασάμενος τὸ τελευταῖον προσέθηκεν, ὡς οὐκ ἄν ποτε δείσειεν ἅλωσιν· θεοῦ γὰρ ὑπάρχειν τὴν πόλιν."},{"number":99,"text":"καὶ ὁ Ἰώσηπος πρὸς ταῦτα ἀνέκραγεν πάνυ γοῦν καθαρὰν τῷ θεῷ τετήρηκας αὐτήν, ἀμίαντον δὲ μένει τὸ ἅγιον, εἰς ὅν τʼ ἐλπίζεις σύμμαχον οὐδὲν ἠσέβησας, τὰς δʼ ἐθίμους θυσίας ἀπολαμβάνει."},{"number":100,"text":"κἂν μὲν σοῦ τις ἀφέλῃ τὴν καθʼ ἡμέραν τροφήν, ἀσεβέστατε, τοῦτον ἥγησαι πολέμιον, αὐτὸν δʼ ὃν τῆς αἰωνίου θρησκείας ἐστέρησας θεὸν ἐλπίζεις σύμμαχον ἔχειν ἐν τῷ πολέμῳ;"},{"number":101,"text":"καὶ Ῥωμαίοις τὰς ἁμαρτίας ἀνατίθης, οἳ μέχρι νῦν κήδονται τῶν ἡμετέρων νόμων καὶ τὰς ὑπὸ σοῦ διακοπείσας θυσίας ἀποδίδοσθαι τῷ θεῷ βιάζονται;"},{"number":102,"text":"τίς οὐκ ἂν στενάξειε καὶ κατολοφύραιτο τῆς παραδόξου μεταβολῆς τὴν πόλιν, εἴ γε ἀλλόφυλοι μὲν καὶ πολέμιοι τὴν σὴν ἀσέβειαν ἐπανορθοῦνται, σὺ δʼ ὁ Ἰουδαῖος, ὁ τοῖς νόμοις ἐντραφείς, κἀκείνων πρὸς αὐτοὺς γίνῃ χαλεπώτερος;"},{"number":103,"text":"ἀλλά τοι, Ἰωάννη, καὶ μετανοῆσαι μὲν ἐκ κακῶν οὐκ αἰσχρὸν ἐν ἐσχάτοις καὶ καλὸν ὑπόδειγμα βουλομένῳ σώζειν τὴν πατρίδα σοι πρόκειται βασιλεὺς Ἰουδαίων Ἰεχονίας,"},{"number":104,"text":"ὅς ποτε στρατεύσαντι τῷ Βαβυλωνίῳ διʼ αὐτὸν ἑκὼν ἐξέστη πρὶν ἁλῶναι τῆς πόλεως καὶ μετὰ γενεᾶς αἰχμαλωσίαν ὑπέμεινεν ἐθελούσιον ὑπὲρ τοῦ μὴ παραδοῦναι ταῦτα πολεμίοις τὰ ἅγια καὶ τὸν οἶκον τοῦ θεοῦ περιιδεῖν φλεγόμενον."},{"number":105,"text":"διὰ τοῦτο λόγος τε αὐτὸν πρὸς ἁπάντων Ἰουδαίων ἱερὸς ὑμνεῖ καὶ μνήμη ῥέουσα διʼ αἰῶνος ἀεὶ νέα τοῖς ἐπιγινομένοις παραδίδωσιν ἀθάνατον."},{"number":106,"text":"καλόν, ὦ Ἰωάννη, ὑπόδειγμα, κἂν προσῇ κίνδυνος· ἐγὼ δέ σοι καὶ τὴν ἀπὸ Ῥωμαίων συγγνώμην ἐγγυῶμαι."},{"number":107,"text":"μέμνησο δʼ ὡς ὁμόφυλος ὢν παραινῶ καὶ Ἰουδαῖος ὢν ἐπαγγέλλομαι, καὶ χρὴ σκοπεῖν τίς ὁ συμβουλεύων καὶ πόθεν. μὴ γὰρ ἔγωγέ ποτε γενοίμην ζῶν οὕτως αἰχμάλωτος, ἵνα παύσωμαι τοῦ γένους ἢ τῶν πατρίων ἐπιλάθωμαι."},{"number":108,"text":"πάλιν ἀγανακτεῖς καὶ κέκραγάς μοι λοιδορούμενος, ἀξίῳ γε καὶ χαλεπωτέρων, ὃς ἀντικρὺς εἱμαρμένης τι παραινῶ καὶ τοὺς ὑπὸ τοῦ θεοῦ βιάζομαι κατακρίτους σώζειν."},{"number":109,"text":"τίς οὐκ οἶδεν τὰς τῶν παλαιῶν προφητῶν ἀναγραφὰς καὶ τὸν ἐπιρρέποντα τῇ τλήμονι πόλει χρησμὸν ἤδη ἐνεστῶτα; τότε γὰρ ἅλωσιν αὐτῆς προεῖπον, ὅταν ὁμοφύλου τις ἄρξῃ φόνου."},{"number":110,"text":"τῶν ὑμετέρων δὲ πτωμάτων οὐχ ἡ πόλις καὶ τὸ ἱερὸν δὲ πᾶν πεπλήρωται; θεὸς ἄρα, θεὸς αὐτὸς ἐπάγει μετὰ Ῥωμαίων κάθαρσιν αὐτῷ πῦρ καὶ τὴν τοσούτων μιασμάτων γέμουσαν πόλιν ἀναρπάζει."},{"number":111,"text":"Ταῦτα λέγων ὁ Ἰώσηπος μετʼ ὀδυρμοῦ καὶ δακρύων λυγμῷ τὴν φωνὴν ἐνεκόπη."},{"number":112,"text":"καὶ Ῥωμαῖοι μὲν ᾤκτειράν τε τοῦ πάθους καὶ τῆς προαιρέσεως αὐτὸν ἐθαύμασαν, οἱ δὲ περὶ τὸν Ἰωάννην παρωξύνοντο μᾶλλον ἐπὶ τοὺς Ῥωμαίους ἐπιθυμοῦντες ἐγκρατεῖς γενέσθαι κἀκείνου."},{"number":113,"text":"τῶν γε μὴν εὐγενῶν πολλοὺς ἐκίνησεν ὁ λόγος, καὶ τινὲς μὲν ὀρρωδοῦντες τὰς φυλακὰς τῶν στασιαστῶν κατὰ χώραν ἔμενον, ἀπώλειαν μέντοι σφῶν τε αὐτῶν καὶ τῆς πόλεως κατεγνώκεσαν, εἰσὶ δὲ οἳ καιροφυλακήσαντες ἄδειαν ἀναχωρήσεως πρὸς τοὺς Ῥωμαίους κατέφυγον."},{"number":114,"text":"ὧν ἦσαν ἀρχιερεῖς μὲν Ἰώσηπός τε καὶ Ἰησοῦς, υἱοὶ δὲ ἀρχιερέων τρεῖς μὲν Ἰσμαήλου τοῦ καρατομηθέντος ἐν Κυρήνῃ, καὶ τέσσαρες Ματθίου καὶ εἷς ἑτέρου Ματθίου, διαδρὰς μετὰ τὴν τοῦ πατρὸς ἀπώλειαν, ὃν ὁ τοῦ Γιώρα Σίμων ἀπέκτεινεν σὺν τρισὶν υἱοῖς, ὡς προείρηται. πολλοὶ δὲ καὶ τῶν ἄλλων εὐγενῶν τοῖς ἀρχιερεῦσι συμμετεβάλοντο."},{"number":115,"text":"Καῖσαρ δὲ αὐτοὺς τά τε ἄλλα φιλοφρόνως ἐδέξατο καὶ γινώσκων ἀλλοφύλοις ἤθεσιν ἀηδῆ τὴν διατριβὴν ἕξειν ἀπέπεμψεν αὐτοὺς εἰς Γόφναν, τέως ἐκεῖ παραινῶν μένειν· ἀποδώσειν γὰρ ἑκάστῳ τὰς κτήσεις κατὰ σχολὴν ἀπὸ τοῦ πολέμου γενόμενος."},{"number":116,"text":"οἱ μὲν οὖν εἰς τὸ δοθὲν πολίχνιον μετὰ πάσης ἀσφαλείας ἀνεχώρουν ἄσμενοι· μὴ φαινομένων δὲ αὐτῶν διεφήμισαν οἱ στασιασταὶ πάλιν ὡς ἀποσφαγεῖεν ὑπὸ Ῥωμαίων οἱ αὐτόμολοι, δηλονότι τοὺς λοιποὺς ἀποτρέποντες τῷ φόβῳ διαδιδράσκειν."},{"number":117,"text":"ἤνυστο δʼ ὡς καὶ πρότερον αὐτοῖς τὸ πανοῦργον πρὸς καιρόν· ἐπεσχέθησαν γὰρ ὑπὸ τοῦ δέους αὐτομολεῖν."},{"number":118,"text":"Αὖθις δέ, ὡς ἀνακαλέσας τοὺς ἄνδρας ἀπὸ τῆς Γοφνὰ Τίτος ἐκέλευσε μετὰ τοῦ Ἰωσήπου περιελθόντας τὸ τεῖχος ὀφθῆναι τῷ δήμῳ, πλεῖστοι πρὸς τοὺς Ῥωμαίους ἔφευγον."},{"number":119,"text":"γενόμενοι δὲ ἀθρόοι καὶ πρὸ τῶν Ῥωμαίων ἱστάμενοι μετʼ οἰμωγῆς καὶ δακρύων ἱκέτευον τοὺς στασιαστὰς τὸ μὲν πρῶτον ὅλῃ τοὺς Ῥωμαίους δέξασθαι τῇ πόλει καὶ τὴν πατρίδα σῶσαι πάλιν,"},{"number":120,"text":"εἰ δὲ μή, τοῦ γε ἱεροῦ πάντως ὑπεξελθεῖν καὶ ῥύσασθαι τὸν ναὸν αὐτοῖς· οὐ γὰρ ἂν τολμῆσαι Ῥωμαίους μὴ μετὰ μεγίστης ἀνάγκης καταφλέξαι τὰ ἅγια."},{"number":121,"text":"τούτοις μᾶλλον ἀντεφιλονείκουν, καὶ πολλὰ βλάσφημα τοῖς αὐτομόλοις ἀντικεκραγότες ἐπὶ τῶν ἱερῶν πυλῶν τούς τε ὀξυβελεῖς καὶ καταπέλτας καὶ λιθοβόλους μηχανὰς διέστησαν, ὡς τὸ κύκλῳ μὲν ἱερὸν ὑπὸ πλήθους νεκρῶν προσεοικέναι πολυανδρίῳ, τὸν δὲ ναὸν αὐτὸν φρουρίῳ."},{"number":122,"text":"τοῖς δὲ ἁγίοις καὶ ἀβάτοις μετὰ τῶν ὅπλων εἰσεπήδων θερμὰς ἔτι τὰς χεῖρας ἐξ ὁμοφύλων ἔχοντες φόνων, καὶ προύκοψαν εἰς τοσοῦτον παρανομίας, ὥσθʼ ἣν ἂν εἰκὸς ἀγανάκτησιν γενέσθαι Ἰουδαίων, εἰ Ῥωμαῖοι ταῦτʼ ἐξύβριζον εἰς αὐτούς, ταύτην εἶναι παρὰ Ῥωμαίων τότε πρὸς Ἰουδαίους ἀσεβοῦντας εἰς τὰ ἴδια."},{"number":123,"text":"τῶν μέν γε στρατιωτῶν οὐκ ἔστιν ὅστις οὐ μετὰ φρίκης εἰς τὸν ναὸν ἀφεώρα καὶ προσεκύνει τούς τε λῃστὰς ηὔχετο πρὶν ἀνηκέστου πάθους μετανοῆσαι."},{"number":124,"text":"Τίτος δὲ ὑπερπαθήσας πάλιν ἐξωνείδιζε τοὺς περὶ τὸν Ἰωάννην, λέγων ἆρʼ οὐχ ὑμεῖς, ὦ μιαρώτατοι, τὸν δρύφακτον τοῦτον προεβάλεσθε τῶν ἁγίων;"},{"number":125,"text":"οὐχ ὑμεῖς δὲ τὰς ἐν αὐτῷ στήλας διεστήσατε, γράμμασιν Ἑλληνικοῖς καὶ ἡμετέροις κεχαραγμένας, μηδένα τὸ γείσιον ὑπερβαίνειν παραγγέλλειν;"},{"number":126,"text":"οὐχ ἡμεῖς δὲ τοὺς ὑπερβάντας ὑμῖν ἀναιρεῖν ἐπετρέψαμεν, κἂν Ῥωμαῖός τις ᾖ; τί οὖν νῦν, ἀλιτήριοι, καὶ νεκροὺς ἐν αὐτῷ καταπατεῖτε; τί δὲ τὸν ναὸν αἵματι ξένῳ καὶ ἐγχωρίῳ φύρετε;"},{"number":127,"text":"μαρτύρομαι θεοὺς ἐγὼ πατρίους καὶ εἴ τις ἐφεώρα ποτὲ τόνδε τὸν χῶρον, νῦν μὲν γὰρ οὐκ οἴομαι, μαρτύρομαι δὲ καὶ στρατιὰν τὴν ἐμὴν καὶ τοὺς παρʼ ἐμοὶ Ἰουδαίους καὶ ὑμᾶς αὐτούς, ὡς οὐκ ἐγὼ ταῦθʼ ὑμᾶς ἀναγκάζω μιαίνειν."},{"number":128,"text":"κἂν ἀλλάξητε τῆς παρατάξεως τὸν τόπον, οὔτε προσελεύσεταί τις Ῥωμαίων τοῖς ἁγίοις οὔτε ἐνυβρίσει, τηρήσω δὲ τὸν ναὸν ὑμῖν καὶ μὴ θέλουσι."},{"number":129,"text":"Ταῦτα τοῦ Ἰωσήπου διαγγέλλοντος ἐκ τοῦ Καίσαρος, οἱ λῃσταὶ καὶ ὁ τύραννος οὐκ ἀπʼ εὐνοίας ἀλλὰ κατὰ δειλίαν γίνεσθαι τὰς παρακλήσεις δοκοῦντες ὑπερηφάνουν."},{"number":130,"text":"Τίτος δὲ ὡς οὔτε οἶκτον ἑαυτῶν τοὺς ἄνδρας οὔτε φειδὼ τοῦ ναοῦ ποιουμένους ἑώρα, πάλιν πρὸς πόλεμον ἄκων ἐχώρει."},{"number":131,"text":"πᾶσαν μὲν οὖν τὴν δύναμιν ἐπάγειν αὐτοῖς οὐχ οἷόν τε ἦν μὴ χωρουμένην τῷ τόπῳ, τριάκοντα δʼ ἐπιλέξας ἀφʼ ἑκάστης ἑκατονταρχίας τοὺς ἀρίστους καὶ τοῖς χιλιάρχοις ἀνὰ χιλίους παραδούς, τούτων δʼ ἐπιτάξας ἡγεμόνα Κερεάλιον, ἐπιθέσθαι προσέταξε ταῖς φυλακαῖς περὶ ὥραν τῆς νυκτὸς ἐνάτην."},{"number":132,"text":"ὄντα δὲ καὶ αὐτὸν ἐν τοῖς ὅπλοις καὶ συγκαταβαίνειν παρεσκευασμένον οἵ τε φίλοι διὰ τὸ μέγεθος τοῦ κινδύνου κατέσχον καὶ τὰ παρὰ τῶν ἡγεμόνων λεγόμενα·"},{"number":133,"text":"πλεῖον γὰρ αὐτὸν ἀνύσειν ἔφασαν ἐπὶ τῆς Ἀντωνίας καθεζόμενον καὶ τὴν μάχην ἀγωνοθετοῦντα τοῖς στρατιώταις ἢ εἰ καταβὰς προκινδυνεύοι· πάντας γὰρ ὁρῶντος Καίσαρος ἀγαθοὺς πολεμιστὰς ἔσεσθαι."},{"number":134,"text":"τούτοις πεισθεὶς Καῖσαρ καὶ διʼ ἓν τοῦτο τοῖς στρατιώταις ὑπομένειν εἰπών, ἵνα κρίνῃ τὰς ἀρετὰς αὐτῶν καὶ μήτε τῶν ἀγαθῶν τις ἀγέραστος μήτε τῶν ἐναντίων ἀτιμώρητος διαλάθῃ, γένηται δὲ αὐτόπτης καὶ μάρτυς ἁπάντων ὁ καὶ τοῦ κολάζειν καὶ τοῦ τιμᾶν κύριος,"},{"number":135,"text":"τοὺς μὲν ἐπὶ τὴν πρᾶξιν ἔπεμπε καθʼ ἣν ὥραν προείρηται, προελθὼν δὲ αὐτὸς εἰς τὸ εὐκάτοπτον ἀπὸ τῆς Ἀντωνίας ἐκαραδόκει τὸ μέλλον."},{"number":136,"text":"Οὐ μὴν οἵ γε πεμφθέντες τοὺς φύλακας εὗρον κοιμωμένους, ὡς ἤλπισαν, ἀλλʼ ἀναπηδήσασι μετὰ κραυγῆς εὐθέως συνεπλέκοντο· πρὸς δὲ τὴν βοὴν τῶν ἐκκοιτούντων ἔνδοθεν οἱ λοιποὶ κατὰ στῖφος ἐξέθεον."},{"number":137,"text":"τῶν μὲν δὴ πρώτων τὰς ὁρμὰς ἐξεδέχοντο Ῥωμαῖοι· περιέπιπτον δʼ οἱ μετʼ ἐκείνους τῷ σφετέρῳ τάγματι, καὶ πολλοὶ τοῖς οἰκείοις ὡς πολεμίοις ἐχρῶντο."},{"number":138,"text":"τὴν μὲν γὰρ διὰ βοῆς ἐπίγνωσιν ἡ κραυγὴ συγχυθεῖσα παρʼ ἀμφοῖν, τὴν δὲ διʼ ὀμμάτων ἡ νὺξ ἕκαστον ἀφείλετο, καὶ τυφλώττειν ἄλλως οὓς μὲν οἱ θυμοὶ παρεσκεύαζον οὓς δʼ οἱ φόβοι· διὰ τοῦτο τὸν προστυχόντα πλήττειν ἦν ἄκριτον."},{"number":139,"text":"Ῥωμαίους μὲν οὖν συνησπικότας καὶ κατὰ συντάξεις προπηδῶντας ἧττον ἔβλαπτεν ἡ ἄγνοια· καὶ γὰρ ἦν παρʼ ἑκάστῳ μνήμη τοῦ συνθήματος·"},{"number":140,"text":"Ἰουδαῖοι δʼ ἀεὶ σκεδαννύμενοι καὶ τάς τε προσβολὰς καὶ τὰς ὑποχωρήσεις ἀνέδην ποιούμενοι πολλάκις φαντασίαν παρεῖχον ἀλλήλοις πολεμίων· τὸν ὑποστρέφοντα γὰρ ἕκαστος οἰκεῖον διὰ σκότους ὡς ἐπιόντα Ῥωμαῖον ἐξεδέχετο."},{"number":141,"text":"πλείους γοῦν ὑπὸ τῶν ἰδίων ἢ τῶν πολεμίων ἐτρώθησαν, ἕως ἡμέρας γενομένης ὄψει τὸ λοιπὸν ἡ μάχη διεκρίνετο, καὶ κατὰ φάλαγγα διαστάντες τοῖς τε βέλεσιν εὐτάκτοις ἐχρῶντο καὶ ταῖς ἀμύναις."},{"number":142,"text":"οὐδέτεροι δὲ οὔτʼ εἶκον οὔτʼ ἐκοπίων, ἀλλʼ οἱ μὲν ὡς ἐφορῶντος Καίσαρος κατʼ ἄνδρα καὶ κατὰ συντάξεις ἤριζον ἀλλήλοις, καὶ προκοπῆς ἕκαστος ἐκείνην αὐτῷ τὴν ἡμέραν ἄρξειν ὑπελάμβανεν, εἰ γενναίως ἀγωνίσαιτο·"},{"number":143,"text":"Ἰουδαίοις δʼ ἐβράβευε τὰς τόλμας ὅ τε περὶ σφῶν αὐτῶν καὶ τοῦ ἱεροῦ φόβος καὶ ὁ τύραννος ἐφεστὼς καὶ τοὺς μὲν παρακαλῶν, τοὺς δὲ μαστιγῶν καὶ διεγείρων ἀπειλαῖς."},{"number":144,"text":"συνέβαινε δὲ τὸ μὲν πλεῖστον σταδιαίαν εἶναι τὴν μάχην, ἐν ὀλίγῳ δὲ καὶ ταχέως ἀντιστρέφεσθαι τὰς ῥοπάς· οὐδέτεροι γὰρ οὔτε φυγῆς οὔτε διώξεως μῆκος εἶχον."},{"number":145,"text":"ἀεὶ δὲ πρὸς τὸ συμβαῖνον οἰκεῖος ἀπὸ τῆς Ἀντωνίας ὁ θόρυβος ἦν, θαρρεῖν δὲ καὶ κρατοῦσι τοῖς σφετέροις ἐπεβόων καὶ μένειν τρεπομένοις."},{"number":146,"text":"ἦν δὲ ὥσπερ τι πολέμου θέατρον· οὐδὲν γὰρ οὔτε Τίτον οὔτε τοὺς περὶ αὐτὸν ἐλάνθανε τῶν κατὰ τὴν μάχην."},{"number":147,"text":"τὸ δὲ πέρας ἀρξάμενοι τῆς νυκτὸς ἐνάτης ὥρας ὑπὲρ πέμπτην τῆς ἡμέρας διελύθησαν ἀφʼ οὗπερ ἤρξαντο τόπου τῆς συμβολῆς, μηδέτεροι βεβαίως κλίναντες τοὺς ἑτέρους, ἀλλὰ τὴν νίκην μέσην ἐν ἀγχωμάλῳ καταλιπόντες."},{"number":148,"text":"καὶ Ῥωμαίων μὲν ἐπισήμως ἠγωνίσαντο πολλοί, Ἰουδαίων δʼ ἐκ μὲν τῶν περὶ Σίμωνα Ἰούδης ὁ τοῦ Μαρεώτου καὶ Σίμων ὁ τοῦ Ὁσαΐα, τῶν δὲ Ἰδουμαίων Ἰάκωβος καὶ Σίμων, Ἀκατελᾶ μὲν οὗτος παῖς, Σωσᾶ δὲ ὁ Ἰάκωβος, τῶν δὲ μετὰ Ἰωάννου Γεφθέος καὶ Ἀλεξᾶς, τῶν δὲ ζηλωτῶν Σίμων υἱὸς Ἀρί."},{"number":149,"text":"Ἐν τούτῳ δʼ ἡ λοιπὴ τῶν Ῥωμαίων δύναμις ἡμέραις ἑπτὰ καταστρεψαμένη τοὺς τῆς Ἀντωνίας θεμελίους μέχρι τοῦ ἱεροῦ πλατεῖαν ὁδὸν εὐτρεπίσαντο."},{"number":150,"text":"πλησιάσαντα δὲ τῷ πρώτῳ περιβόλῳ τὰ τάγματα κατήρχετο χωμάτων, τὸ μὲν ἀντικρὺς τῆς τοῦ εἴσω ἱεροῦ γωνίας, ἥτις ἦν κατʼ ἄρκτον καὶ δύσιν, τὸ δὲ κατὰ τὴν βόρειον ἐξέδραν, ἣ μεταξὺ τῶν δύο πυλῶν ἦν·"},{"number":151,"text":"τῶν δὲ λοιπῶν δύο θάτερον μὲν κατὰ τὴν ἑσπέριον στοὰν τοῦ ἔξωθεν ἱεροῦ, τὸ δʼ ἕτερον ἔξω κατὰ τὴν βόρειον. προύκοπτεν μέντοι μετὰ πολλοῦ καμάτου καὶ ταλαιπωρίας αὐτοῖς τὰ ἔργα [καὶ] τὴν ὕλην ἀφʼ ἑκατὸν σταδίων συγκομίζουσιν,"},{"number":152,"text":"ἐκακοῦντο δʼ ἔσθʼ ὅπη καὶ κατʼ ἐπιβουλάς, αὐτοὶ διὰ περιουσίαν τοῦ κρατεῖν ὄντες ἀδεέστεροι καὶ διʼ ἀπόγνωσιν ἤδη σωτηρίας χρώμενοι τολμηροτέροις τοῖς Ἰουδαίοις."},{"number":153,"text":"τῶν γὰρ ἱππέων τινὲς ὁπότε προέλθοιεν ἐπὶ ξυλείαν ἢ χόρτου συλλογήν, τὸν τῆς συγκομιδῆς χρόνον ἀνίεσαν βόσκεσθαι τοὺς ἵππους ἀποχαλινοῦντες, οὓς οἱ Ἰουδαῖοι κατὰ στῖφος ἐκπηδῶντες ἥρπαζον."},{"number":154,"text":"καὶ τούτου συνεχῶς γινομένου νομίσας Καῖσαρ, ὅπερ ἦν, ἀμελείᾳ τῶν σφετέρων πλέον ἢ τῇ Ἰουδαίων ἀνδρείᾳ γίνεσθαι τὰς ἁρπαγάς, ἔγνω σκυθρωπότερον τοὺς λοιποὺς πρὸς φυλακὴν τῶν ἵππων ἐπιστρέψαι."},{"number":155,"text":"καὶ κελεύσας ἀπαχθῆναι τὴν ἐπὶ θανάτῳ τῶν ἀπολεσάντων στρατιωτῶν ἕνα, φόβῳ τοῖς ἄλλοις ἐτήρησε τοὺς ἵππους· οὐκέτι γὰρ εἴων νέμεσθαι, καθάπερ δὲ συμπεφυκότες αὐτοῖς ἐπὶ τὰς χρείας ἐξῄεσαν."},{"number":156,"text":"οἱ μὲν οὖν προσεπολέμουν τῷ ἱερῷ καὶ τὰ χώματα διήγειρον."},{"number":157,"text":"Μετὰ δὲ μίαν ἡμέραν αὐτῶν τῆς ἀνόδου πολλοὶ τῶν στασιαστῶν, οἷς ἁρπαγαί τε ἐπέλειπον ἤδη καὶ ὁ λιμὸς ἤπειγε, συνελθόντες ταῖς κατὰ τὸ Ἐλαιῶν ὄρος Ῥωμαίων φυλακαῖς ἐπιτίθενται περὶ ὥραν ἑνδεκάτην τῆς ἡμέρας, οἰόμενοι πρῶτον μὲν ἀδοκήτων, ἔπειτα πρὸς θεραπείαις ἤδη τοῦ σώματος ὄντων ῥᾳδίως διεκπαίσειν."},{"number":158,"text":"προαισθόμενοι δὲ τὴν ἔφοδον αὐτῶν οἱ Ῥωμαῖοι καὶ ταχέως ἐκ τῶν πλησίον φρουρίων συνδραμόντες εἶργον ὑπερπηδᾶν καὶ διακόπτειν τὸ περιτείχισμα βιαζομένους."},{"number":159,"text":"γενομένης δὲ καρτερᾶς τῆς συμβολῆς ἄλλα τε πολλὰ παρʼ ἑκατέρων γενναίως ἐπράχθη, Ῥωμαίων μὲν μετὰ τῆς ἰσχύος ἐμπειρίᾳ τοῦ πολεμεῖν χρωμένων, Ἰουδαίων δὲ ἀφειδέσι ταῖς ὁρμαῖς καὶ τοῖς θυμοῖς ἀκατασχέτοις·"},{"number":160,"text":"ἐστρατήγει δὲ τῶν μὲν αἰδώς, τῶν δὲ ἀνάγκη· τό τε γὰρ ἐξαφεῖναι Ἰουδαίους ὥσπερ ἄρκυσιν ἐνειλημμένους Ῥωμαίοις αἴσχιστον ἐδόκει, κἀκεῖνοι μίαν ἐλπίδα σωτηρίας εἶχον, εἰ βιασάμενοι ῥήξειαν τὸ τεῖχος·"},{"number":161,"text":"καὶ τῶν ἀπὸ σπείρας τις ἱππέων, Πεδάνιος τοὔνομα, τρεπομένων ἤδη τῶν Ἰουδαίων καὶ κατὰ τῆς φάραγγος συνωθουμένων ῥόθιον ἐκ πλαγίου παρελαύνων τὸν ἵππον ἁρπάζει τινὰ φεύγοντα τῶν πολεμίων, νεανίαν στιβαρόν τε ἄλλως τὸ σῶμα καὶ καθωπλισμένον, δραξάμενος ἐκ τοῦ σφυροῦ·"},{"number":162,"text":"τοσοῦτον μὲν ἑαυτὸν ἐκ τρέχοντος ἐπέκλινε τοῦ ἵππου, τοσοῦτον δὲ ἐπεδείξατο τῆς δεξιᾶς τὸν τόνον καὶ τοῦ λοιποῦ σώματος ἔτι δʼ ἐμπειρίας ἱππικῆς."},{"number":163,"text":"ὁ μὲν οὖν ὥσπερ τι κειμήλιον ἁρπασάμενος ἧκε φέρων Καίσαρι τὸν αἰχμάλωτον· Τίτος δὲ τὸν μὲν λαβόντα τῆς δυνάμεως θαυμάσας, τὸν δὲ ληφθέντα τῆς περὶ τὸ τεῖχος ἐπιχειρήσεως κολάσαι κελεύσας, αὐτὸς ἐν ταῖς περὶ τὸ ἱερὸν διαμάχαις ἦν καὶ τὰ χώματα κατήπειγεν."},{"number":164,"text":"Ἐν ᾧ Ἰουδαῖοι κακούμενοι ταῖς συμβολαῖς ἀεὶ κατʼ ὀλίγον κορυφουμένου τοῦ πολέμου καὶ τῷ ναῷ προσέρποντος, καθάπερ σηπομένου σώματος ἀπέκοπτον τὰ προειλημμένα μέλη φθάνοντες τὴν εἰς τὸ πρόσω νομήν."},{"number":165,"text":"τῆς γὰρ βορείου καὶ κατὰ δύσιν στοᾶς τὸ συνεχὲς πρὸς τὴν Ἀντωνίαν ἐμπρήσαντες ἔπειτα ἀπέρρηξαν ὅσον πήχεις εἴκοσι, ταῖς ἰδίαις χερσὶν ἀρξάμενοι καίειν τὰ ἅγια."},{"number":166,"text":"μετὰ δʼ ἡμέρας δύο, τετράδι καὶ εἰκάδι τοῦ προειρημένου μηνός, τὴν πλησίον στοὰν ὑποπιμπρᾶσι Ῥωμαῖοι, καὶ μέχρι πεντεκαίδεκα πηχῶν προκόψαντος τοῦ πυρὸς ἀποκόπτουσιν ὁμοίως Ἰουδαῖοι τὴν ὀροφήν, μήτε καθάπαξ ἐξιστάμενοι τῶν ἔργων καὶ τὸ πρὸς τὴν Ἀντωνίαν συναφὲς αὐτῶν διαιροῦντες·"},{"number":167,"text":"διὸ καὶ παρὸν κωλύειν ὑποπιμπράντας, οἱ δὲ πρὸς τὴν ἐμβολὴν τοῦ πυρὸς ἠρεμήσαντες τὴν νομὴν ἐμέτρησαν αὐτῷ σφίσι χρησίμως."},{"number":168,"text":"περὶ μὲν δὴ τὸ ἱερὸν οὐ διέλειπον αἱ συμβολαί, συνεχὴς δʼ ἦν κατὰ μέρος ἐκθεόντων ἐπʼ ἀλλήλους ὁ πόλεμος."},{"number":169,"text":"Τῶν Ἰουδαίων δέ τις κατὰ ταύτας τὰς ἡμέρας ἀνὴρ τό τε σῶμα βραχὺς καὶ τὴν ὄψιν εὐκαταφρόνητος γένους θʼ ἕνεκα καὶ τῶν ἄλλων ἄσημος, Ἰωνάθης ἐκαλεῖτο, προελθὼν κατὰ τὸ τοῦ ἀρχιερέως Ἰωάννου μνημεῖον ἄλλα τε πολλὰ πρὸς τοὺς Ῥωμαίους ὑπερηφάνως ἐφθέγγετο καὶ τὸν ἄριστον αὐτῶν εἰς μονομαχίαν προυκαλεῖτο."},{"number":170,"text":"τῶν δὲ ταύτῃ παρατεταγμένων οἱ πολλοὶ μὲν ὑπερηφάνουν, ἦσαν δʼ οἳ κατὰ τὸ εἰκὸς ἐδεδοίκεσαν, ἥπτετό γε μὴν τινῶν καὶ λογισμὸς οὐκ ἀσύνετος θανατῶντι μὴ συμπλέκεσθαι·"},{"number":171,"text":"τοὺς γὰρ ἀπεγνωκότας τὴν σωτηρίαν ἅμα καὶ τὰς ὁρμὰς ἀταμιεύτους ἔχειν καὶ τὸ θεῖον εὐδυσώπητον, τό τε παραβάλλεσθαι πρὸς οὓς καὶ τὸ νικᾶν οὐ μέγα καὶ μετʼ αἰσχύνης τὸ λειφθῆναι σφαλερόν, οὐκ ἀνδρείας ἀλλὰ θρασύτητος εἶναι."},{"number":172,"text":"μηδενὸς δʼ ἐπὶ πολὺ προϊόντος καὶ τοῦ Ἰουδαίου πολλὰ κατακερτομοῦντος αὐτοὺς εἰς δειλίαν, ἀλαζὼν γάρ τις ἦν αὑτῷ σφόδρα καὶ τῶν Ῥωμαίων ὑπερήφανος, Πούδης τις ὄνομα τῶν ἐξ ἴλης ἱππέων βδελυξάμενος αὐτοῦ τά τε ῥήματα καὶ τὸ αὔθαδες,"},{"number":173,"text":"εἰκὸς δὲ καὶ πρὸς τὴν βραχύτητα τοῦ σώματος αὐτὸν ἀσκέπτως ἐπαρθῆναι, προπηδᾷ, καὶ τὰ μὲν ἄλλα περιῆν συμβαλών, προεδόθη δὲ ὑπὸ τῆς τύχης· πεσόντα γὰρ αὐτὸν ὁ Ἰωνάθης ἀποσφάττει προσδραμών."},{"number":174,"text":"ἔπειτα ἐπιβὰς τῷ νεκρῷ τό τε ξίφος ᾑμαγμένον ἀνέσειε καὶ τῇ λαιᾷ τὸν θυρεὸν ἐπηλάλαξέ τε τῇ στρατιᾷ πολλὰ καὶ πρὸς τὸν πεσόντα κομπάζων καὶ τοὺς ὁρῶντας Ῥωμαίους ἐπισκώπτων,"},{"number":175,"text":"ἕως αὐτὸν ἀνασκιρτῶντα καὶ ματαΐζοντα Πρῖσκός τις ἑκατοντάρχης τοξεύσας διήλασε βέλει· πρὸς ὃ τῶν τε Ἰουδαίων καὶ τῶν Ῥωμαίων κραυγὴ συνεξήρθη διάφορος."},{"number":176,"text":"ὁ δὲ δινηθεὶς ἐκ τῶν ἀλγηδόνων ἐπὶ τὸ σῶμα τοῦ πολεμίου κατέπεσεν, ὠκυτάτην ἀποφήνας ἐν πολέμῳ τὴν ἐπὶ τῷ ἀλόγως εὐτυχοῦντι νέμεσιν."}],"3":[{"number":177,"text":"Οἱ δὲ ἀνὰ τὸ ἱερὸν στασιασταὶ φανερῶς τε οὐκ ἀνίεσαν τοὺς ἐπὶ τῶν χωμάτων στρατιώτας ἀμυνόμενοι καθʼ ἑκάστην ἡμέραν, καὶ τοῦ προειρημένου μηνὸς ἑβδόμῃ καὶ εἰκάδι δόλον ἐνσκευάζονται τοιόνδε."},{"number":178,"text":"τῆς ἑσπερίου στοᾶς τὸ μεταξὺ τῶν δοκῶν καὶ τῆς ὑπʼ αὐτῆς ὀροφῆς ὕλης ἀναπιμπλᾶσιν αὔης, πρὸς δὲ ἀσφάλτου τε καὶ πίσσης· ἔπειθʼ ὡς καταπονούμενοι δῆθεν ὑπεχώρουν."},{"number":179,"text":"πρὸς ὃ τῶν μὲν ἀσκέπτων πολλοὶ ταῖς ὁρμαῖς φερόμενοι προσέκειντο τοῖς ὑποχωροῦσιν ἐπί τε τὴν στοὰν ἀνεπήδων προσθέμενοι κλίμακας, οἱ δὲ συνετώτεροι τὴν ἄλογον τροπὴν τῶν Ἰουδαίων ὑπονοήσαντες ἔμενον."},{"number":180,"text":"κατεπλήσθη μέντοι τῶν ἀναπηδησάντων ἡ στοά, κἀν τούτῳ Ἰουδαῖοι πᾶσαν ὑποπιμπρᾶσιν αὐτήν. αἰρομένης δʼ αἰφνιδίως πάντοθεν τῆς φλογὸς τούς τε ἔξω τοῦ κινδύνου Ῥωμαίους ἔκπληξις ἐπέσχε δεινὴ καὶ τοὺς περισχεθέντας ἀμηχανία."},{"number":181,"text":"κυκλούμενοι δὲ ὑπὸ τῆς φλογὸς οἱ μὲν εἰς τὴν πόλιν ὀπίσω κατεκρήμνιζον ἑαυτούς, οἱ δʼ εἰς τοὺς πολεμίους, πολλοὶ δʼ ἐλπίδι σωτηρίας εἰς τοὺς σφετέρους καταπηδῶντες ἐκλῶντο τὰ μέλη, πλείστων δʼ ἔφθανε τὰς ὁρμὰς τὸ πῦρ καί τινες τὴν φλόγα σιδήρῳ."},{"number":182,"text":"περιεῖχε δʼ εὐθέως καὶ τοὺς ἄλλως φθειρομένους τὸ πῦρ ἐπὶ πλεῖστον ἐκφερόμενον. Καίσαρα δὲ καίπερ χαλεπαίνοντα τοῖς ἀπολλυμένοις, ἐπειδὴ δίχα παραγγέλματος ἀναβεβήκεσαν, ὅμως οἶκτος εἰσῄει τῶν ἀνδρῶν·"},{"number":183,"text":"καὶ μηδενὸς προσαμύνειν δυναμένου, τοῦτο γοῦν παραμύθιον ἦν τοῖς φθειρομένοις τὸ βλέπειν ὑπὲρ οὗ τις ἠφίει τὴν ψυχὴν ὀδυνώμενον· βοῶν τε γὰρ αὐτοῖς καὶ προπηδῶν καὶ τοῖς περὶ αὐτὸν ἐκ τῶν ἐνόντων ἐπαμύνειν παρακαλῶν δῆλος ἦν."},{"number":184,"text":"τὰς δὲ φωνὰς ἕκαστος καὶ τὴν διάθεσιν ὥσπερ τι λαμπρὸν ἀποφέρων ἐντάφιον εὔθυμος ἀπέθνησκεν."},{"number":185,"text":"ἔνιοί γε μὴν ἐπὶ τὸν τοῖχον τῆς στοᾶς ὄντα πλατὺν ἀναχωρήσαντες ἐκ μὲν τοῦ πυρὸς διεσώθησαν, ὑπὸ δὲ τῶν Ἰουδαίων περισχεθέντες ἐπὶ πολὺ μὲν ἀντέσχον διατιτρωσκόμενοι, τέλος δὲ πάντες ἔπεσον,"},{"number":186,"text":"καὶ τελευταῖός τις αὐτῶν νεανίας, ὀνόματι Λόγγος, ὅλον ἐπικοσμήσας τὸ πάθος καὶ κατʼ ἄνδρα μνήμης ἀξίων ὄντων πάντων τῶν ἀπολωλότων ἄριστος φανείς."},{"number":187,"text":"ὃν οἱ μὲν Ἰουδαῖοι τῆς τε ἀλκῆς ἀγάμενοι καὶ ἄλλως ἀνελεῖν ἀσθενοῦντες καταβῆναι πρὸς αὐτοὺς ἐπὶ δεξιᾷ παρεκάλουν, ὁ δὲ ἀδελφὸς Κορνήλιος ἐκ θατέρου μὴ καταισχῦναι τὸ σφέτερον κλέος καὶ τὴν Ῥωμαίων στρατιάν. τούτῳ πεισθεὶς καὶ διαράμενος φανερὸν ἑκατέροις τοῖς τάγμασι τὸ ξίφος αὑτὸν ἀναιρεῖ."},{"number":188,"text":"τῶν δὲ τῷ πυρὶ περισχεθέντων Ἀρτώριός τις πανουργίᾳ διασώζεται· προσκαλεσάμενος γάρ τινα τῶν στρατιωτῶν Λούκιον, ᾧ συνεσκήνει, μεγάλῃ τῇ φωνῇ κληρονόμον, ἔφη, καταλείπω σε τῶν ἐμαυτοῦ κτημάτων, εἰ προσελθών με δέξαιο."},{"number":189,"text":"τοῦ δὲ ἑτοίμως προσδραμόντος ὁ μὲν ἐπʼ αὐτὸν κατενεχθεὶς ἔζησεν, ὁ δὲ δεξάμενος ὑπὸ τοῦ βάρους τῷ λιθοστρώτῳ προσαραχθεὶς παραχρῆμα θνήσκει."},{"number":190,"text":"τοῦτο τὸ πάθος πρὸς καιρὸν μὲν Ῥωμαίοις ἐνεποίησεν ἀθυμίαν, πρὸς δὲ τὸ μέλλον ὅμως ἀπαρακλήτους κατεσκεύασεν φυλακτικωτέρους τε πρὸς τὰς Ἰουδαίων ἀπάτας ὠφέλησεν, ἐν αἷς τὰ πολλὰ διʼ ἄγνοιαν τῶν τόπων καὶ τὸ ἦθος τῶν ἀνδρῶν ἐβλάπτοντο."},{"number":191,"text":"κατεκάη δʼ ἡ στοὰ μέχρι τοῦ Ἰωάννου πύργου, ὃν ἐκεῖνος ἐν τῷ πρὸς Σίμωνα πολέμῳ κατεσκεύασεν ὑπὲρ τὰς ἐξαγούσας ὑπὲρ τὸν ξυστὸν πύλας· τὸ δὲ λοιπὸν ἐπὶ διεφθαρμένοις ἤδη Ἰουδαῖοι τοῖς ἀναβᾶσιν ἀπέκοψαν."},{"number":192,"text":"τῇ δʼ ὑστεραίᾳ καὶ Ῥωμαῖοι τὴν βόρειον στοὰν ἐνέπρησαν μέχρι τῆς ἀνατολικῆς ὅλην, ὧν ἡ συνάπτουσα γωνία τῆς Κεδρῶνος καλουμένης φάραγγος ὑπερδεδόμητο, παρʼ ὃ καὶ φοβερὸν ἦν τὸ βάθος. καὶ τὰ μὲν περὶ τὸ ἱερὸν ἐν τούτοις ἦν."},{"number":193,"text":"Τῶν δὲ ὑπὸ τοῦ λιμοῦ φθειρομένων κατὰ τὴν πόλιν ἄπειρον μὲν ἔπιπτε τὸ πλῆθος, ἀδιήγητα δὲ συνέβαινε τὰ πάθη."},{"number":194,"text":"καθʼ ἑκάστην γὰρ οἰκίαν, εἴ που τροφῆς παραφανείη σκιά, πόλεμος ἦν, καὶ διὰ χειρῶν ἐχώρουν οἱ φίλτατοι πρὸς ἀλλήλους ἐξαρπάζοντες τὰ ταλαίπωρα τῆς ψυχῆς ἐφόδια."},{"number":195,"text":"πίστις δʼ ἀπορίας οὐδὲ τοῖς θνήσκουσιν ἦν, ἀλλὰ καὶ τοὺς ἐκπνέοντας οἱ λῃσταὶ διηρεύνων, μή τις ὑπὸ κόλπον ἔχων τροφὴν σκήπτοιτο τὸν θάνατον αὑτῷ."},{"number":196,"text":"οἱ δʼ ὑπʼ ἐνδείας κεχηνότες ὥσπερ λυσσῶντες κύνες ἐσφάλλοντο, καὶ παρεφέροντο ταῖς τε θύραις ἐνσειόμενοι μεθυόντων τρόπον καὶ ὑπʼ ἀμηχανίας εἰς τοὺς αὐτοὺς οἴκους εἰσπηδῶντες δὶς ἢ τρὶς ὥρᾳ μιᾷ."},{"number":197,"text":"πάντα δὲ ὑπʼ ὀδόντας ἦγεν ἡ ἀνάγκη, καὶ τὰ μηδὲ τοῖς ῥυπαρωτάτοις τῶν ἀλόγων ζῴων πρόσφορα συλλέγοντες ἐσθίειν ὑπέφερον· ζωστήρων γοῦν καὶ ὑποδημάτων τὸ τελευταῖον οὐκ ἀπέσχοντο καὶ τὰ δέρματα τῶν θυρεῶν ἀποδέροντες ἐμασῶντο."},{"number":198,"text":"τροφὴ δʼ ἦν καὶ χόρτου τισὶ παλαιοῦ σπάραγμα· τὰς γὰρ ἶνας ἔνιοι συλλέγοντες ἐλάχιστον σταθμὸν ἐπώλουν Ἀττικῶν τεσσάρων."},{"number":199,"text":"καὶ τί δεῖ τὴν ἐπʼ ἀψύχοις ἀναίδειαν τοῦ λιμοῦ λέγειν; εἶμι γὰρ αὐτοῦ δηλώσων ἔργον οἷον μήτε παρʼ Ἕλλησιν μήτε παρὰ βαρβάροις ἱστόρηται, φρικτὸν μὲν εἰπεῖν, ἄπιστον δὲ ἀκοῦσαι."},{"number":200,"text":"καὶ ἔγωγε μὴ δόξαιμι τερατεύεσθαι τοῖς αὖθις ἀνθρώποις, κἂν παρέλειπον τὴν συμφορὰν ἡδέως, εἰ μὴ τῶν κατʼ ἐμαυτὸν εἶχον ἀπείρους μάρτυρας. ἄλλως τε καὶ ψυχρὰν ἂν καταθείμην τῇ πατρίδι χάριν καθυφέμενος τὸν λόγον ὧν πέπονθεν τὰ ἔργα."},{"number":201,"text":"Γυνή τις τῶν ὑπὲρ τὸν Ἰορδάνην κατοικούντων, Μαρία τοὔνομα, πατρὸς Ἐλεαζάρου, κώμης Βηθεζουβᾶ, σημαίνει δὲ τοῦτο οἶκος ὑσσώπου, διὰ γένος καὶ πλοῦτον ἐπίσημος, μετὰ τοῦ λοιποῦ πλήθους εἰς τὰ Ἱεροσόλυμα καταφυγοῦσα συνεπολιορκεῖτο."},{"number":202,"text":"ταύτης τὴν μὲν ἄλλην κτῆσιν οἱ τύραννοι διήρπασαν, ὅσην ἐκ τῆς Περαίας ἀνασκευασαμένη μετήνεγκεν εἰς τὴν πόλιν, τὰ δὲ λείψανα τῶν κειμηλίων καὶ εἴ τι τροφῆς ἐπινοηθείη καθʼ ἡμέραν εἰσπηδῶντες ἥρπαζον οἱ δορυφόροι."},{"number":203,"text":"δεινὴ δὲ τὸ γύναιον ἀγανάκτησις εἰσῄει, καὶ πολλάκις λοιδοροῦσα καὶ καταρωμένη τοὺς ἅρπαγας ἐφʼ αὑτὴν ἠρέθιζεν."},{"number":204,"text":"ὡς δʼ οὔτε παροξυνόμενός τις οὔτʼ ἐλεῶν αὐτὴν ἀνῄρει, καὶ τὸ μὲν εὑρεῖν τι σιτίον ἄλλοις ἐκοπία, πανταχόθεν δὲ ἄπορον ἦν ἤδη καὶ τὸ εὑρεῖν, ὁ λιμὸς δὲ διὰ σπλάγχνων καὶ μυελῶν ἐχώρει καὶ τοῦ λιμοῦ μᾶλλον ἐξέκαιον οἱ θυμοί, σύμβουλον λαβοῦσα τὴν ὀργὴν μετὰ τῆς ἀνάγκης ἐπὶ τὴν φύσιν ἐχώρει,"},{"number":205,"text":"καὶ τὸ τέκνον, ἦν δὲ αὐτῇ παῖς ὑπομάστιος, ἁρπασαμένη βρέφος, εἶπεν, ἄθλιον, ἐν πολέμῳ καὶ λιμῷ καὶ στάσει τίνι σε τηρήσω;"},{"number":206,"text":"τὰ μὲν παρὰ Ῥωμαίοις δουλεία, κἂν ζήσωμεν ἐπʼ αὐτούς, φθάνει δὲ καὶ δουλείαν ὁ λιμός, οἱ στασιασταὶ δὲ ἀμφοτέρων χαλεπώτεροι."},{"number":207,"text":"ἴθι, γενοῦ μοι τροφὴ καὶ τοῖς στασιασταῖς ἐρινὺς καὶ τῷ βίῳ μῦθος ὁ μόνος ἐλλείπων ταῖς Ἰουδαίων συμφοραῖς."},{"number":208,"text":"καὶ ταῦθʼ ἅμα λέγουσα κτείνει τὸν υἱόν, ἔπειτʼ ὀπτήσασα τὸ μὲν ἥμισυ κατεσθίει, τὸ δὲ λοιπὸν κατακαλύψασα ἐφύλαττεν."},{"number":209,"text":"εὐθέως δʼ οἱ στασιασταὶ παρῆσαν, καὶ τῆς ἀθεμίτου κνίσης σπάσαντες ἠπείλουν, εἰ μὴ δείξειεν τὸ παρασκευασθέν, ἀποσφάξειν αὐτὴν εὐθέως. ἡ δὲ καὶ μοῖραν αὐτοῖς εἰποῦσα καλὴν τετηρηκέναι τὰ λείψανα τοῦ τέκνου διεκάλυψεν."},{"number":210,"text":"τοὺς δʼ εὐθέως φρίκη καὶ παρέκστασις ᾕρει καὶ παρὰ τὴν ὄψιν ἐπεπήγεσαν. ἡ δʼ ἐμόν, ἔφη, τοῦτο τέκνον γνήσιον καὶ τὸ ἔργον ἐμόν."},{"number":211,"text":"φάγετε, καὶ γὰρ ἐγὼ βέβρωκα. μὴ γένησθε μήτε μαλακώτεροι γυναικὸς μήτε συμπαθέστεροι μητρός. εἰ δʼ ὑμεῖς εὐσεβεῖς καὶ τὴν ἐμὴν ἀποστρέφεσθε θυσίαν, ἐγὼ μὲν ὑμῖν βέβρωκα, καὶ τὸ λοιπὸν δὲ ἐμοὶ μεινάτω."},{"number":212,"text":"μετὰ ταῦθʼ οἱ μὲν τρέμοντες ἐξῄεσαν, πρὸς ἓν τοῦτο δειλοὶ καὶ μόλις ταύτης τῆς τροφῆς τῇ μητρὶ παραχωρήσαντες, ἀνεπλήσθη δʼ εὐθέως ὅλη τοῦ μύσους ἡ πόλις, καὶ πρὸ ὀμμάτων ἕκαστος τὸ πάθος λαμβάνων ὥσπερ αὐτῷ τολμηθὲν ἔφριττε."},{"number":213,"text":"σπουδὴ δὲ τῶν λιμωττόντων ἐπὶ τὸν θάνατον ἦν, καὶ μακαρισμὸς τῶν φθασάντων πρὶν ἀκοῦσαι καὶ θεάσασθαι κακὰ τηλικαῦτα."},{"number":214,"text":"Ταχέως δὲ καὶ Ῥωμαίοις διηγγέλθη τὸ πάθος. τῶν δʼ οἱ μὲν ἠπίστουν, οἱ δὲ ᾤκτειρον, τοὺς δὲ πολλοὺς εἰς μῖσος τοῦ ἔθνους σφοδρότερον συνέβη προελθεῖν."},{"number":215,"text":"Καῖσαρ δὲ ἀπελογεῖτο καὶ περὶ τούτου τῷ θεῷ, φάσκων παρὰ μὲν αὐτοῦ Ἰουδαίοις εἰρήνην καὶ αὐτονομίαν προτείνεσθαι καὶ πάντων ἀμνηστίαν τῶν τετολμημένων, τοὺς δὲ ἀντὶ μὲν ὁμονοίας στάσιν,"},{"number":216,"text":"ἀντὶ δὲ εἰρήνης πόλεμον, πρὸ κόρου δὲ καὶ εὐθηνίας λιμὸν αἱρουμένους, ἰδίαις δὲ χερσὶν ἀρξαμένους καίειν τὸ συντηρούμενον ὑφʼ ἡμῶν ἱερὸν αὐτοῖς, εἶναι καὶ τοιαύτης τροφῆς ἀξίους."},{"number":217,"text":"καλύψειν μέντοι τὸ τῆς τεκνοφαγίας μύσος αὐτῷ τῷ τῆς πατρίδος πτώματι καὶ οὐ καταλείψειν ἐπὶ τῆς οἰκουμένης ἡλίῳ καθορᾶν πόλιν, ἐν ᾗ μητέρες οὕτω τρέφονται."},{"number":218,"text":"προσήκειν μέντοι πρὸ μητέρων πατράσιν τὴν τοιαύτην τροφήν, οἳ καὶ μετὰ τηλικαῦτα πάθη μένουσιν ἐν τοῖς ὅπλοις."},{"number":219,"text":"ταῦθʼ ἅμα διεξιὼν ἐνενόει καὶ τὴν ἀπόγνωσιν τῶν ἀνδρῶν· οὐ γὰρ ἂν ἔτι σωφρονῆσαι τοὺς πάντα προπεπονθότας ἐφʼ οἷς εἰκὸς ἦν μεταβαλέσθαι μὴ παθοῦσιν."}],"4":[{"number":220,"text":"Ἤδη δὲ τῶν δύο ταγμάτων συντετελεκότων τὰ χώματα Λώου μηνὸς ὀγδόῃ προσάγειν ἐκέλευσε τοὺς κριοὺς κατὰ τὴν ἑσπέριον ἐξέδραν τοῦ ἔξωθεν ἱεροῦ."},{"number":221,"text":"πρὸ δὲ τούτων ἓξ ἡμέρας ἀδιαλείπτως ἡ στερροτάτη πασῶν ἑλέπολις τύπτουσα τὸν τοῖχον οὐδὲν ἤνυσεν, ἀλλὰ καὶ ταύτης καὶ τῶν ἄλλων τὸ μέγεθος καὶ ἡ ἁρμονία τῶν λίθων ἦν ἀμείνων."},{"number":222,"text":"τῆς δὲ βορείου πύλης ὑπώρυττον ἕτεροι τοὺς θεμελίους καὶ πολλὰ ταλαιπωρήσαντες τοὺς ἔμπροσθεν λίθους ἐξεκύλισαν. ἀνείχοντο δʼ ὑπὸ τῶν ἐνδοτέρω καὶ διέμεινεν ἡ πύλη, μέχρι τὰς διʼ ὀργάνων καὶ τῶν μοχλῶν ἐπιχειρήσεις ἀπογνόντες κλίμακας ταῖς στοαῖς προσέφερον."},{"number":223,"text":"οἱ δὲ Ἰουδαῖοι κωλῦσαι μὲν οὐκ ἔφθασαν, ἀναβᾶσι δὲ συμπεσόντες ἐμάχοντο, καὶ τοὺς μὲν ἀνωθοῦντες εἰς τοὐπίσω κατεκρήμνιζον, τοὺς δʼ ὑπαντιάζοντας ἀνῄρουν·"},{"number":224,"text":"πολλοὺς δὲ τῶν κλιμάκων ἀποβαίνοντας πρὶν φράξασθαι τοῖς θυρεοῖς παίοντες ταῖς ῥομφαίαις ἔφθανον, ἐνίας δὲ γεμούσας ὁπλιτῶν κλίμακας παρακλίνοντες ἄνωθεν κατέσειον·"},{"number":225,"text":"ἦν δʼ οὐκ ὀλίγος καὶ αὐτῶν φόνος. οἱ δὲ ἀνενεγκόντες τὰς σημαίας περὶ αὐτῶν ἐπολέμουν, δεινὴν ἡγούμενοι καὶ πρὸς αἰσχύνης τούτων τὴν ἁρπαγήν."},{"number":226,"text":"τέλος δὲ καὶ τῶν σημαιῶν οἱ Ἰουδαῖοι κρατοῦσιν καὶ τοὺς ἀναβάντας διαφθείρουσιν· οἱ δὲ λοιποὶ πρὸς τὸ τῶν ἀπολωλότων πάθος ὀρρωδοῦντες ἀνεχώρουν."},{"number":227,"text":"τῶν μὲν οὖν Ῥωμαίων ἄπρακτος οὐδεὶς ἀπέθανεν, τῶν δὲ στασιαστῶν οἳ κατὰ τὰς προτέρας μάχας ἠγωνίσαντο γενναίως καὶ τότε καὶ Ἐλεάζαρος ἀδελφιδοῦς τοῦ τυράννου Σίμωνος."},{"number":228,"text":"ὁ δὲ Τίτος ὡς ἑώρα τὴν ἐπὶ τοῖς ἀλλοτρίοις ἱεροῖς φειδὼ πρὸς βλάβης τοῖς στρατιώταις γινομένην καὶ φόνου, τὰς πύλας προσέταξεν ὑφάπτειν."},{"number":229,"text":"Ἐν δὲ τούτῳ πρὸς αὐτὸν αὐτομολοῦσιν Ἄνανός τε ὁ ἀφαμμαούς, τῶν Σίμωνος δορυφόρων ὁ φονικώτατος, καὶ Ἀρχέλαος υἱὸς Μαγαδδάτου, συγγνώμην ἐλπίσαντες ἐπειδὴ κρατούντων Ἰουδαίων ἀπεχώρουν."},{"number":230,"text":"Τίτος δὲ καὶ τοῦτο τὸ πανούργημα προβάλλεται τῶν ἀνδρῶν, καὶ τὴν ἄλλην περὶ τοὺς ἰδίους ὠμότητα πεπυσμένος ὥρμητο κτείνειν ἑκατέρους, ὑπʼ ἀνάγκης ἦχθαι λέγων αὐτούς, οὐκ ἐκ προαιρέσεως παρεῖναι, καὶ σωτηρίας οὐκ ἀξίους εἶναι τοὺς φλεγομένης ἤδη διʼ αὐτοὺς τῆς πατρίδος ἐξαλλομένους."},{"number":231,"text":"ἐκράτει δʼ ὅμως τοῦ θυμοῦ ἡ πίστις, καὶ ἀφίησι τοὺς ἄνδρας, οὐ μὴν ἐν ἴσῃ μοίρᾳ κατέτασσε τοῖς ἄλλοις."},{"number":232,"text":"ἤδη δὲ ταῖς πύλαις οἱ στρατιῶται προσῆγον τὸ πῦρ, καὶ περιτηκόμενος ὁ ἄργυρος διεδίδου ταχέως εἰς τὴν ξυλείαν τὴν φλόγα, ἔνθεν ἀθρόως ἐκφερομένη τῶν στοῶν ἐπελαμβάνετο."},{"number":233,"text":"τοῖς δὲ Ἰουδαίοις ὁρῶσι τὸ πῦρ ἐν κύκλῳ μετὰ τῶν σωμάτων παρείθησαν αἱ ψυχαί, καὶ διὰ τὴν κατάπληξιν ἀμύνειν μὲν ἢ σβεννύειν ὥρμησεν οὐδείς, αὖοι δʼ ἑστῶτες ἀφεώρων."},{"number":234,"text":"οὐ μὴν πρὸς τὸ δαπανώμενον ἀθυμοῦντες εἰς γοῦν τὸ λοιπὸν ἐσωφρόνουν, ἀλλʼ ὡς ἤδη καὶ τοῦ ναοῦ καιομένου τοὺς θυμοὺς ἐπὶ Ῥωμαίους ἔθηγον."},{"number":235,"text":"ἐκείνην μὲν οὖν τὴν ἡμέραν καὶ τὴν ἐπιοῦσαν νύκτα τὸ πῦρ ἐπεκράτει· κατὰ μέρος γάρ, οὐχ ὁμοῦ πάντοθεν ἴσχυσαν ὑφάψαι τὰς στοάς."},{"number":236,"text":"Τῇ δʼ ἐπιούσῃ Τίτος μέρει τῆς δυνάμεως σβεννύειν τε καὶ τὰ παρὰ τὰς πύλας ὁδοποιεῖν εἰς εὐμαρεστέραν τῶν ταγμάτων ἄνοδον κελεύσας αὐτὸς συνῆγε τοὺς ἡγεμόνας."},{"number":237,"text":"καὶ συνελθόντων ἓξ τῶν κορυφαιοτάτων, Τιβερίου τε Ἀλεξάνδρου τοῦ πάντων τῶν στρατευμάτων ἐπάρχοντος, καὶ Σέξτου Κερεαλίου τοῦ τὸ πέμπτον ἄγοντος τάγμα, καὶ Λαρκίου Λεπίδου τὸ δέκατον, καὶ Τίτου Φρυγίου τὸ πεντεκαιδέκατον,"},{"number":238,"text":"πρὸς οἷς Φρόντων ἦν Ἑτέριος στρατοπεδάρχης τῶν ἀπὸ Ἀλεξανδρείας δύο ταγμάτων, καὶ Μᾶρκος Ἀντώνιος Ἰουλιανὸς ὁ τῆς Ἰουδαίας ἐπίτροπος, καὶ μετὰ τούτους ἐπιτρόπων καὶ χιλιάρχων ἀθροισθέντων, βουλὴν περὶ τοῦ ναοῦ προυτίθει."},{"number":239,"text":"τοῖς μὲν οὖν ἐδόκει χρῆσθαι τῷ τοῦ πολέμου νόμῳ· μὴ γὰρ ἄν ποτε Ἰουδαίους παύσασθαι νεωτερίζοντας τοῦ ναοῦ μένοντος, ἐφʼ ὃν οἱ πανταχόθεν συλλέγονται."},{"number":240,"text":"τινὲς δὲ παρῄνουν, εἰ μὲν καταλίποιεν αὐτὸν Ἰουδαῖοι καὶ μηδεὶς ἐπʼ αὐτοῦ τὰ ὅπλα θείη, σώζειν, εἰ δὲ πολεμοῖεν ἐπιβάντες, καταφλέγειν· φρούριον γάρ, οὐκέτι ναὸν εἶναι, καὶ τὸ λοιπὸν ἔσεσθαι τῶν ἀναγκασάντων τὴν ἀσέβειαν, οὐκ αὐτῶν."},{"number":241,"text":"ὁ δὲ Τίτος οὐδʼ ἂν ἐπιβάντες ἐπʼ αὐτοῦ πολεμῶσιν Ἰουδαῖοι φήσας ἀντὶ τῶν ἀνδρῶν ἀμυνεῖσθαι τὰ ἄψυχα οὐδὲ καταφλέξειν ποτὲ τηλικοῦτον ἔργον· Ῥωμαίων γὰρ ἔσεσθαι τὴν βλάβην, ὥσπερ καὶ κόσμον τῆς ἡγεμονίας αὐτοῦ μένοντος·"},{"number":242,"text":"θαρροῦντες δὲ ἤδη προσετίθεντο τῇ γνώμῃ Φρόντων τε καὶ Ἀλέξανδρος καὶ Κερεάλιος."},{"number":243,"text":"τότε μὲν οὖν διαλύει τὸ συνέδριον καὶ τὰς ἄλλας δυνάμεις διαναπαῦσαι κελεύσας τοῖς ἡγεμόσιν, ὅπως ἐρρωμενεστέροις ἐν τῇ παρατάξει χρήσαιτο, τοῖς ἀπὸ τῶν σπειρῶν ἐπιλέκτοις ὁδοποιεῖν διὰ τῶν ἐρειπίων προσέταξε καὶ τὸ πῦρ σβεννύειν."},{"number":244,"text":"Κατʼ ἐκείνην μὲν δὴ τὴν ἡμέραν τῶν Ἰουδαίων κάματός τε καὶ κατάπληξις ἐκράτησε τὰς ὁρμάς· τῇ δʼ ἐπιούσῃ συλλεξάμενοί τε τὴν ἰσχὺν καὶ ἀναθαρσήσαντες ἐπεκθέουσι διὰ τῆς ἀνατολικῆς πύλης τοῖς φύλαξι τοῦ ἔξωθεν ἱεροῦ περὶ δευτέραν ὥραν."},{"number":245,"text":"οἱ δὲ καρτερῶς μὲν ἐδέξαντο αὐτῶν τὴν ἐμβολὴν καὶ φραξάμενοι τοῖς θυρεοῖς κατὰ μέτωπον ὥσπερ τεῖχος ἐπύκνωσαν τὴν φάλαγγα, δῆλοι δʼ ἦσαν οὐκ ἐπὶ πολὺ συμμενοῦντες πλήθει τε τῶν ἐκτρεχόντων καὶ θυμοῖς ἡττώμενοι."},{"number":246,"text":"φθάσας δὲ τῆς παρατάξεως τὴν ῥοπὴν Καῖσαρ, καθεώρα γὰρ ἀπὸ τῆς Ἀντωνίας, ἐπήμυνε μετὰ τῶν ἐπιλέκτων ἱππέων."},{"number":247,"text":"Ἰουδαῖοι δὲ τὴν ἔφοδον οὐχ ὑπέμειναν, ἀλλὰ τῶν πρώτων πεσόντων ἐτράπησαν οἱ πολλοί·"},{"number":248,"text":"καὶ ὑποχωροῦσι μὲν τοῖς Ῥωμαίοις ἐπιστρεφόμενοι προσέκειντο, μεταβαλλομένων δὲ ἀνέφευγον πάλιν, ἕως περὶ πέμπτην τῆς ἡμέρας ὥραν οἱ μὲν βιασθέντες εἰς τὸ ἔνδον συνεκλείσθησαν ἱερόν."},{"number":249,"text":"Τίτος δὲ ἀνεχώρησεν εἰς τὴν Ἀντωνίαν διεγνωκὼς τῆς ἐπιούσης ἡμέρας ὑπὸ τὴν ἕω μετὰ πάσης ἐμβαλεῖν τῆς δυνάμεως καὶ τὸν ναὸν περικατασχεῖν."},{"number":250,"text":"τοῦ δʼ ἄρα κατεψήφιστο μὲν τὸ πῦρ ὁ θεὸς πάλαι, παρῆν δʼ ἡ εἱμαρμένη χρόνων περιόδοις ἡμέρα δεκάτη Λώου μηνός, καθʼ ἣν καὶ πρότερον ὑπὸ τοῦ τῶν Βαβυλωνίων βασιλέως ἐνεπρήσθη."},{"number":251,"text":"λαμβάνουσι δʼ αἱ φλόγες ἐκ τῶν οἰκείων τὴν ἀρχὴν καὶ τὴν αἰτίαν· ὑποχωρήσαντος γὰρ τοῦ Τίτου πρὸς ὀλίγον λωφήσαντες οἱ στασιασταὶ πάλιν τοῖς Ῥωμαίοις ἐπιτίθενται, καὶ τῶν τοῦ ναοῦ φρουρῶν γίνεται συμβολὴ πρὸς τοὺς σβεννύντας τὸ πῦρ τοῦ ἔνδοθεν ἱεροῦ, οἳ τρεψάμενοι τοὺς Ἰουδαίους μέχρι τοῦ ναοῦ παρηκολούθουν."},{"number":252,"text":"ἔνθα δὴ τῶν στρατιωτῶν τις οὔτε παράγγελμα περιμείνας οὔτʼ ἐπὶ τηλικούτῳ δείσας ἐγχειρήματι, δαιμονίῳ ὁρμῇ τινι χρώμενος ἁρπάζει μὲν ἐκ τῆς φλεγομένης † φλογός, ἀνακουφισθεὶς δὲ ὑπὸ συστρατιώτου τὸ πῦρ ἐνίησι θυρίδι χρυσῇ, καθʼ ἣν εἰς τοὺς περὶ τὸν ναὸν οἴκους εἰσιτὸν ἦν ἐκ τοῦ βορείου κλίματος."},{"number":253,"text":"αἰρομένης δὲ τῆς φλογὸς Ἰουδαίων μὲν ἐγείρεται κραυγὴ τοῦ πάθους ἀξία, καὶ πρὸς τὴν ἄμυναν συνέθεον, οὔτε τοῦ ζῆν ἔτι φειδὼ λαμβάνοντες οὔτε ταμιευόμενοι τὴν ἰσχύν, διʼ ὃ φυλακτικοὶ πρότερον ἦσαν οἰχομένου."},{"number":254,"text":"Δραμὼν δέ τις ἀγγέλλει Τίτῳ· κἀκεῖνος, ἔτυχεν δὲ κατὰ σκηνὴν ἀναπαυόμενος ἐκ τῆς μάχης, ὡς εἶχεν ἀναπηδήσας ἔθει πρὸς τὸν ναὸν εἴρξων τὸ πῦρ."},{"number":255,"text":"κατόπιν δὲ οἵ τε ἡγεμόνες εἵποντο πάντες, καὶ πτοηθέντα τούτοις ἠκολούθει τὰ τάγματα· βοὴ δὲ ἦν καὶ θόρυβος ἅτε τηλικαύτης δυνάμεως ἀτάκτως κεκινημένης."},{"number":256,"text":"ὁ μὲν οὖν Καῖσαρ τῇ τε φωνῇ καὶ τῇ δεξιᾷ διεσήμαινε τοῖς μαχομένοις τὸ πῦρ σβεννύειν, οὔτε δὲ βοῶντος ἤκουον μείζονι κραυγῇ τὰς ἀκοὰς προκατειλημμένοι καὶ τοῖς νεύμασι τῆς χειρὸς οὐ προσεῖχον, οἱ μὲν τῷ πολεμεῖν, οἱ δὲ ὀργῇ περισπώμενοι."},{"number":257,"text":"τῶν δὲ ταγμάτων εἰσθεόντων οὔτε παραίνεσις οὔτʼ ἀπειλὴ κατεῖχεν τὰς ὁρμάς, ἀλλʼ ὁ θυμὸς ἁπάντων ἐστρατήγει· καὶ περὶ τὰς εἰσόδους συνωθούμενοι πολλοὶ μὲν ὑπʼ ἀλλήλων κατεπατοῦντο, πολλοὶ δὲ θερμοῖς ἔτι καὶ τυφομένοις τοῖς ἐρειπίοις τῶν στοῶν ἐμπίπτοντες ἡττωμένων συμφοραῖς ἐχρῶντο."},{"number":258,"text":"πλησίον δὲ τοῦ ναοῦ γινόμενοι τῶν μὲν τοῦ Καίσαρος παραγγελμάτων προσεποιοῦντο μηδὲ κατακούειν, τοῖς πρὸ αὐτῶν δὲ τὸ πῦρ ἐνιέναι παρεκελεύοντο."},{"number":259,"text":"τῶν δὲ στασιαστῶν ἀμηχανία μὲν ἦν ἤδη τοῦ βοηθεῖν, φόνος δὲ πανταχοῦ καὶ τροπή. τὸ δὲ πλέον ἀπὸ τοῦ δήμου λαὸς ἀσθενὴς καὶ ἄνοπλος ὅπου καταληφθείη τις ἀπεσφάττετο, καὶ περὶ μὲν τὸν βωμὸν πλῆθος ἐσωρεύετο νεκρῶν, κατὰ δὲ τῶν τοῦ ναοῦ βάθρων αἷμά τʼ ἔρρει πολὺ καὶ τὰ τῶν ἄνω φονευομένων σώματα κατωλίσθανε."},{"number":260,"text":"Καῖσαρ δʼ ὡς οὔτε τὰς ὁρμὰς ἐνθουσιώντων τῶν στρατιωτῶν κατασχεῖν οἷός τε ἦν καὶ τὸ πῦρ ἐπεκράτει, παρελθὼν μετὰ τῶν ἡγεμόνων ἔνδον ἐθεάσατο τοῦ ναοῦ τὸ ἅγιον καὶ τὰ ἐν αὐτῷ, πολὺ μὲν τῆς παρὰ τοῖς ἀλλοφύλοις φήμης ἀμείνω, τοῦ δὲ κόμπου καὶ τῆς παρὰ τοῖς οἰκείοις δόξης οὐκ ἐλάττω."},{"number":261,"text":"τῆς φλογὸς δὲ οὐδέπω διικνουμένης οὐδαμόθεν εἴσω, τοὺς δὲ περὶ τὸν ναὸν οἴκους νεμομένης, νομίσας, ὅπερ ἦν, ἔτι σώζεσθαι τὸ ἔργον δύνασθαι προπηδᾷ,"},{"number":262,"text":"καὶ αὐτός τε παρακαλεῖν τοὺς στρατιώτας ἐπειρᾶτο τὸ πῦρ σβεννύειν καὶ Λιβεράλιον ἑκατοντάρχην τῶν περὶ αὐτὸν λογχοφόρων ξύλοις παίοντα τοὺς ἀπειθοῦντας ἐκέλευσεν εἴργειν."},{"number":263,"text":"τῶν δὲ καὶ τὴν πρὸς τὸν Καίσαρα αἰδῶ καὶ τὸν ἀπὸ τοῦ κωλύοντος φόβον ἐνίκων οἱ θυμοὶ καὶ τὸ πρὸς Ἰουδαίους μῖσος, καὶ πολεμική τις ὁρμὴ λαβροτέρα·"},{"number":264,"text":"τοὺς δὲ πολλοὺς ἐνῆγεν ἁρπαγῆς ἐλπίς, δόξαν τε ἔχοντας ὡς τὰ ἔνδον ἅπαντα χρημάτων μεστὰ εἴη, καὶ τὰ πέριξ ὁρῶντας χρυσοῦ πεποιημένα."},{"number":265,"text":"φθάνει δέ τις καὶ τῶν εἴσω παρεληλυθότων ἐκπηδήσαντος τοῦ Καίσαρος πρὸς ἐποχὴν τῶν στρατιωτῶν πῦρ εἰς τοὺς στροφέας ἐμβαλὼν τῆς πύλης † ἐν σκότῳ·"},{"number":266,"text":"τότε γὰρ ἐξαπίνης ἔνδοθεν ἐκφανείσης φλογὸς οἵ τε ἡγεμόνες μετὰ τοῦ Καίσαρος ἀνεχώρουν, καὶ τοὺς ἔξωθεν οὐδεὶς ὑφάπτειν ἐκώλυεν. ὁ μὲν οὖν ναὸς οὕτως ἄκοντος Καίσαρος ἐμπίπραται."},{"number":267,"text":"Πολλὰ δʼ ἄν τις ἐπολοφυράμενος ἔργῳ πάντων ὧν ὄψει καὶ ἀκοῇ παρειλήφαμεν θαυμασιωτάτῳ κατασκευῆς τε ἕνεκα καὶ μεγέθους ἔτι τε τῆς καθʼ ἕκαστον πολυτελείας καὶ τῆς περὶ τὰ ἅγια δόξης, μεγίστην λάβοι παραμυθίαν τὴν εἱμαρμένην ἄφυκτον οὖσαν ὥσπερ ἐμψύχοις οὕτω καὶ ἔργοις καὶ τόποις."},{"number":268,"text":"θαυμάσαι δʼ ἄν τις ἐν αὐτῇ τῆς περιόδου τὴν ἀκρίβειαν· καὶ μῆνα γοῦν, ὡς ἔφην, καὶ ἡμέραν ἐτήρησεν τὴν αὐτήν, ἐν ᾗ πρότερον ὑπὸ Βαβυλωνίων ὁ ναὸς ἐνεπρήσθη."},{"number":269,"text":"καὶ ἀπὸ μὲν τῆς πρώτης αὐτοῦ κτίσεως, ἣν κατεβάλετο Σολομὼν ὁ βασιλεύς; μέχρι τῆς νῦν ἀναιρέσεως, ἣ γέγονεν ἔτει δευτέρῳ τῆς Οὐεσπασιανοῦ ἡγεμονίας, ἔτη συνάγεται χίλια ἑκατὸν τριάκοντα, πρὸς δὲ μῆνες ἑπτὰ καὶ πεντεκαίδεκα ἡμέραι·"},{"number":270,"text":"ἀπὸ δὲ τῆς ὕστερον, ἣν ἔτει δευτέρῳ Κύρου βασιλεύοντος ἐποιήσατο Ἀγγαῖος, ἔτη μέχρι τῆς ὑπὸ Οὐεσπασιανοῦ ἁλώσεως τριακονταεννέα πρὸς ἑξακοσίοις καὶ ἡμέραι τεσσαρακονταπέντε."}],"5":[{"number":271,"text":"Καιομένου δὲ τοῦ ναοῦ τῶν μὲν προσπιπτόντων ἦν ἁρπαγή, φόνος δὲ τῶν καταλαμβανομένων μυρίος καὶ οὔτε ἡλικίας ἦν ἔλεος οὔτʼ ἐντροπὴ σεμνότητος, ἀλλὰ καὶ παιδία καὶ γέροντες καὶ βέβηλοι καὶ ἱερεῖς ὁμοίως ἀνῃροῦντο, καὶ πᾶν γένος ἐπεξῄει περισχὼν ὁ πόλεμος, ὁμοῦ τούς τε ἱκετεύοντας καὶ τοὺς ἀμυνομένους."},{"number":272,"text":"συνήχει δὲ ἡ φλὸξ ἐπὶ πλεῖστον ἐκφερομένη τοῖς τῶν πιπτόντων στεναγμοῖς, καὶ διὰ μὲν τὸ ὕψος τοῦ λόφου καὶ τὸ τοῦ φλεγομένου μέγεθος ἔργου πᾶσαν ἄν τις ἔδοξε καίεσθαι τὴν πόλιν, τῆς δὲ βοῆς ἐκείνης οὐδὲν ἐπινοηθῆναι δύναιτʼ ἂν ἢ μεῖζον ἢ φοβερώτερον."},{"number":273,"text":"τῶν τε γὰρ Ῥωμαϊκῶν ταγμάτων ἀλαλαγμὸς ἦν συμφερομένων, καὶ τῶν στασιαστῶν πυρὶ καὶ σιδήρῳ κεκυκλωμένων κραυγή, τοῦ τε ἀποληφθέντος ἄνω λαοῦ τροπή τε μετʼ ἐκπλήξεως εἰς τοὺς πολεμίους καὶ πρὸς τὸ πάθος οἰμωγαί."},{"number":274,"text":"συνεβόα δὲ τοῖς ἐπὶ τοῦ λόφου τὸ κατὰ τὴν πόλιν πλῆθος· ἤδη δὲ πολλοὶ τῷ λιμῷ μαραινόμενοι καὶ μεμυκότες ὡς εἶδον τὸ τοῦ ναοῦ πῦρ, εἰς ὀδυρμοὺς πάλιν καὶ κραυγὴν εὐτόνησαν· συνήχει δὲ ἥ τε Περαία καὶ τὰ πέριξ ὄρη βαρυτέραν ποιοῦντα τὴν βοήν."},{"number":275,"text":"ἦν δὲ τοῦ θορύβου τὰ πάθη φοβερώτερα· τὸν μέν γε τοῦ ἱεροῦ λόφον ἐκ ῥιζῶν ἄν τις ἔδοξε βράττεσθαι πάντοθεν τοῦ πυρὸς καταγέμοντα, δαψιλέστερον δὲ τὸ αἷμα τοῦ πυρὸς εἶναι καὶ τῶν φονευόντων πλείους τοὺς φονευομένους·"},{"number":276,"text":"οὐδαμοῦ γὰρ ἡ γῆ διεφαίνετο τῶν νεκρῶν, ἀλλὰ σωροῖς ἐπιβαίνοντες οἱ στρατιῶται σωμάτων ἐπὶ τοὺς διαφεύγοντας ἔθεον."},{"number":277,"text":"τὸ μὲν οὖν λῃστρικὸν πλῆθος ὠσάμενοι τοὺς Ῥωμαίους μόλις εἰς τὸ ἔξω διεκπίπτουσιν ἱερὸν κἀκεῖθεν εἰς τὴν πόλιν, τοῦ δημοτικοῦ δὲ τὸ λειφθὲν ἐπὶ τὴν ἔξω στοὰν κατέφυγε."},{"number":278,"text":"τῶν δὲ ἱερέων τινὲς τὸ μὲν πρῶτον ἀπὸ τοῦ ναοῦ τούς τε ὀβελοὺς καὶ τὰς ἕδρας αὐτῶν μολίβου πεποιημένας ἀνασπῶντες εἰς τοὺς Ῥωμαίους ἠφίεσαν,"},{"number":279,"text":"αὖθις δὲ ὡς οὔτε ἤνυόν τι καὶ τὸ πῦρ ἐπʼ αὐτοὺς ἀνερρήγνυτο, ἐπὶ τὸν τοῖχον ἀναχωρήσαντες ὄντα ὀκτάπηχυν τὸ εὖρος ἔμενον."},{"number":280,"text":"δύο γε μὴν τῶν ἐπισήμων, παρὸν σωθῆναι πρὸς Ῥωμαίους μεταστᾶσιν ἢ διακαρτερεῖν πρὸς τὴν μετὰ τῶν ἄλλων τύχην, ἑαυτοὺς ἔρριψαν εἰς τὸ πῦρ καὶ τῷ ναῷ συγκατεφλέγησαν, Μηϊρός τε υἱὸς Βελγᾶ καὶ Ἰώσηπος Δαλαίου."},{"number":281,"text":"Ῥωμαῖοι δὲ μάταιον τὴν ἐπὶ τοῖς πέριξ φειδὼ κρίναντες τοῦ ναοῦ φλεγομένου πάντα συνεπίμπρασαν, τά τε λείψανα τῶν στοῶν καὶ τὰς πύλας πλὴν δύο, τῆς μὲν ἐκ τῶν ἀνατολικῶν τῆς δὲ μεσημβρινῆς· καὶ ταύτας ὕστερον κατέσκαψαν."},{"number":282,"text":"ἔκαιον δὲ καὶ τὰ γαζοφυλάκια, ἐν οἷς ἄπειρον μὲν χρημάτων πλῆθος ἄπειροι δʼ ἐσθῆτες καὶ ἄλλα κειμήλια, συνελόντι δʼ εἰπεῖν, πᾶς ὁ Ἰουδαίων σεσώρευτο πλοῦτος, ἀνεσκευασμένων ἐκεῖ τοὺς οἴκους τῶν εὐπόρων."},{"number":283,"text":"ἧκον δὲ καὶ ἐπὶ τὴν λοιπὴν στοὰν τοῦ ἔξωθεν ἱεροῦ· καταφεύγει δʼ ἐπʼ αὐτὴν ἀπὸ τοῦ δήμου γύναια καὶ παιδία καὶ σύμμικτος ὄχλος εἰς ἑξακισχιλίους."},{"number":284,"text":"πρὶν δὲ Καίσαρα κρῖναί τι περὶ αὐτῶν ἢ κελεῦσαι τοὺς ἡγεμόνας, φερόμενοι τοῖς θυμοῖς οἱ στρατιῶται τὴν στοὰν ὑφάπτουσι, καὶ συνέβη τοὺς μὲν ῥιπτοῦντας αὑτοὺς ἐκ τῆς φλογὸς διαφθαρῆναι, τοὺς δὲ ἐν αὐτῇ· περιεσώθη δὲ ἐκ τοσούτων οὐδείς."},{"number":285,"text":"τούτοις αἴτιος τῆς ἀπωλείας ψευδοπροφήτης τις κατέστη κατʼ ἐκείνην κηρύξας τὴν ἡμέραν τοῖς ἐπὶ τῆς πόλεως, ὡς ὁ θεὸς ἐπὶ τὸ ἱερὸν ἀναβῆναι κελεύει δεξομένους τὰ σημεῖα τῆς σωτηρίας."},{"number":286,"text":"πολλοὶ δʼ ἦσαν ἐγκάθετοι παρὰ τῶν τυράννων τότε πρὸς τὸν δῆμον προφῆται προσμένειν τὴν ἀπὸ τοῦ θεοῦ βοήθειαν καταγγέλλοντες, ὡς ἧττον αὐτομολοῖεν καὶ τοὺς ἐπάνω δέους καὶ φυλακῆς γενομένους ἐλπὶς παρακροτοίη."},{"number":287,"text":"πείθεται δὲ ταχέως ἄνθρωπος ἐν συμφοραῖς, ὅταν δʼ ἤδη καὶ τῶν κατεχόντων δεινῶν ἀπαλλαγὴν ὁ ἐξαπατῶν ὑπογράφῃ, τόθʼ ὁ πάσχων ὅλος γίνεται τῆς ἐλπίδος."},{"number":288,"text":"Τὸν γοῦν ἄθλιον δῆμον οἱ μὲν ἀπατεῶνες καὶ καταψευδόμενοι τοῦ θεοῦ τηνικαῦτα παρέπειθον, τοῖς δʼ ἐναργέσι καὶ προσημαίνουσι τὴν μέλλουσαν ἐρημίαν τέρασιν οὔτε προσεῖχον οὔτʼ ἐπίστευον, ἀλλʼ ὡς ἐμβεβροντημένοι καὶ μήτε ὄμματα μήτε ψυχὴν ἔχοντες τῶν τοῦ θεοῦ κηρυγμάτων παρήκουσαν,"},{"number":289,"text":"τοῦτο μὲν ὅτε ὑπὲρ τὴν πόλιν ἄστρον ἔστη ῥομφαίᾳ παραπλήσιον καὶ παρατείνας ἐπʼ ἐνιαυτὸν κομήτης,"},{"number":290,"text":"τοῦτο δʼ ἡνίκα πρὸ τῆς ἀποστάσεως καὶ τοῦ πρὸς τὸν πόλεμον κινήματος ἀθροιζομένου τοῦ λαοῦ πρὸς τὴν τῶν ἀζύμων ἑορτήν, ὀγδόη δʼ ἦν Ξανθικοῦ μηνός, κατὰ νυκτὸς ἐνάτην ὥραν τοσοῦτο φῶς περιέλαμψε τὸν βωμὸν καὶ τὸν ναόν, ὡς δοκεῖν ἡμέραν εἶναι λαμπράν, καὶ τοῦτο παρέτεινεν ἐφʼ ἡμίσειαν ὥραν·"},{"number":291,"text":"ὃ τοῖς μὲν ἀπείροις ἀγαθὸν ἐδόκει, τοῖς δὲ ἱερογραμματεῦσι πρὸς τῶν ἀποβεβηκότων εὐθέως ἐκρίθη."},{"number":292,"text":"καὶ κατὰ τὴν αὐτὴν ἑορτὴν βοῦς μὲν ἀχθεῖσα ὑπό του πρὸς τὴν θυσίαν ἔτεκεν ἄρνα ἐν τῷ ἱερῷ μέσῳ,"},{"number":293,"text":"ἡ δʼ ἀνατολικὴ πύλη τοῦ ἐνδοτέρω ναοῦ χαλκῆ μὲν οὖσα καὶ στιβαρωτάτη, κλειομένη δὲ περὶ δείλην μόλις ὑπʼ ἀνθρώπων εἴκοσι, καὶ μοχλοῖς μὲν ἐπερειδομένη σιδηροδέτοις, κατάπηγας δὲ ἔχουσα βαθυτάτους εἰς τὸν οὐδὸν ὄντα διηνεκοῦς λίθου καθιεμένους, ὤφθη κατὰ νυκτὸς ὥραν ἕκτην αὐτομάτως ἠνοιγμένη."},{"number":294,"text":"δραμόντες δὲ οἱ τοῦ ἱεροῦ φύλακες ἤγγειλαν τῷ στρατηγῷ, κἀκεῖνος ἀναβὰς μόλις αὐτὴν ἴσχυσεν κλεῖσαι."},{"number":295,"text":"πάλιν τοῦτο τοῖς μὲν ἰδιώταις κάλλιστον ἐδόκει τέρας· ἀνοῖξαι γὰρ τὸν θεὸν αὐτοῖς τὴν τῶν ἀγαθῶν πύλην· οἱ λόγιοι δὲ λυομένην αὐτομάτως τοῦ ναοῦ τὴν ἀσφάλειαν ἐνενόουν, καὶ πολεμίοις δῶρον ἀνοίγεσθαι τὴν πύλην, δηλωτικόν τε ἐρημίας ἀπέφαινον ἐν αὑτοῖς τὸ σημεῖον."},{"number":296,"text":"μετὰ δὲ τὴν ἑορτὴν οὐ πολλαῖς ἡμέραις ὕστερον, μιᾷ καὶ εἰκάδι Ἀρτεμισίου μηνός, φάσμα τι δαιμόνιον ὤφθη μεῖζον πίστεως·"},{"number":297,"text":"τερατεία δὲ ἂν ἔδοξεν οἶμαι τὸ ῥηθησόμενον, εἰ μὴ καὶ παρὰ τοῖς θεασαμένοις ἱστόρητο καὶ τὰ ἐπακολουθήσαντα πάθη τῶν σημείων ἦν ἄξια·"},{"number":298,"text":"πρὸ γὰρ ἡλίου δύσεως ὤφθη μετέωρα περὶ πᾶσαν τὴν χώραν ἅρματα καὶ φάλαγγες ἔνοπλοι διᾴττουσαι τῶν νεφῶν καὶ κυκλούμεναι τὰς πόλεις."},{"number":299,"text":"κατὰ δὲ τὴν ἑορτήν, ἣ πεντηκοστὴ καλεῖται, νύκτωρ οἱ ἱερεῖς παρελθόντες εἰς τὸ ἔνδον ἱερόν, ὥσπερ αὐτοῖς ἔθος πρὸς τὰς λειτουργίας, πρῶτον μὲν κινήσεως ἔφασαν ἀντιλαβέσθαι καὶ κτύπου, μετὰ δὲ ταῦτα φωνῆς ἀθρόας μεταβαίνομεν ἐντεῦθεν."},{"number":300,"text":"τὸ δὲ τούτων φοβερώτερον, Ἰησοῦς γάρ τις υἱὸς Ἀνανίου τῶν ἰδιωτῶν ἄγροικος πρὸ τεσσάρων ἐτῶν τοῦ πολέμου τὰ μάλιστα τῆς πόλεως εἰρηνευομένης καὶ εὐθηνούσης, ἐλθὼν εἰς τὴν ἑορτήν, ἐν ᾗ σκηνοποιεῖσθαι πάντας ἔθος τῷ θεῷ, κατὰ τὸ ἱερὸν ἐξαπίνης ἀναβοᾶν ἤρξατο"},{"number":301,"text":"φωνὴ ἀπὸ ἀνατολῆς, φωνὴ ἀπὸ δύσεως, φωνὴ ἀπὸ τῶν τεσσάρων ἀνέμων, φωνὴ ἐπὶ Ἱεροσόλυμα καὶ τὸν ναόν, φωνὴ ἐπὶ νυμφίους καὶ νύμφας, φωνὴ ἐπὶ τὸν λαὸν πάντα. τοῦτο μεθʼ ἡμέραν καὶ νύκτωρ κατὰ πάντας τοὺς στενωποὺς περιῄει κεκραγώς."},{"number":302,"text":"τῶν δὲ ἐπισήμων τινὲς δημοτῶν ἀγανακτήσαντες πρὸς τὸ κακόφημον συλλαμβάνουσι τὸν ἄνθρωπον καὶ πολλαῖς αἰκίζονται πληγαῖς. ὁ δὲ οὔθʼ ὑπὲρ αὑτοῦ φθεγξάμενος οὔτε ἰδίᾳ πρὸς τοὺς παίοντας, ἃς καὶ πρότερον φωνὰς βοῶν διετέλει."},{"number":303,"text":"νομίσαντες δὲ οἱ ἄρχοντες, ὅπερ ἦν, δαιμονιώτερον τὸ κίνημα τἀνδρὸς ἀνάγουσιν αὐτὸν ἐπὶ τὸν παρὰ Ῥωμαίοις ἔπαρχον."},{"number":304,"text":"ἔνθα μάστιξι μέχρι ὀστέων ξαινόμενος οὔθʼ ἱκέτευσεν οὔτʼ ἐδάκρυσεν, ἀλλʼ ὡς ἐνῆν μάλιστα τὴν φωνὴν ὀλοφυρτικῶς παρεγκλίνων πρὸς ἑκάστην"},{"number":305,"text":"ἀπεκρίνατο πληγήν αἰαὶ Ἱεροσολύμοις. τοῦ δʼ Ἀλβίνου διερωτῶντος, οὗτος γὰρ ἔπαρχος ἦν, τίς εἴη καὶ πόθεν, καὶ διὰ τί ταῦτα φθέγγοιτο, πρὸς ταῦτα μὲν οὐδʼ ὁτιοῦν ἀπεκρίνατο, τὸν δὲ ἐπὶ τῇ πόλει θρῆνον εἴρων οὐ διέλειπεν, μέχρι καταγνοὺς μανίαν ὁ Ἀλβῖνος ἀπέλυσεν αὐτόν."},{"number":306,"text":"ὁ δὲ τὸν μέχρι τοῦ πολέμου χρόνον οὔτε προσῄει τινὶ τῶν πολιτῶν οὔτε ὤφθη λαλῶν, ἀλλὰ καθʼ ἡμέραν ὥσπερ εὐχὴν μεμελετηκώς αἰαὶ Ἱεροσολύμοις ἐθρήνει."},{"number":307,"text":"οὔτε δέ τινι τῶν τυπτόντων αὐτὸν ὁσημέραι κατηρᾶτο οὔτε τοὺς τροφῆς μεταδιδόντας εὐλόγει, μία δὲ πρὸς πάντας ἦν ἡ σκυθρωπὴ κλῃδὼν ἀπόκρισις."},{"number":308,"text":"μάλιστα δʼ ἐν ταῖς ἑορταῖς ἐκεκράγει· καὶ τοῦτʼ ἐφʼ ἑπτὰ ἔτη καὶ μῆνας πέντε εἴρων οὔτʼ ἤμβλυνεν τὴν φωνὴν οὔτʼ ἔκαμεν, μέχρις οὗ κατὰ τὴν πολιορκίαν ἔργα τῆς κλῃδόνος ἰδὼν ἀνεπαύσατο."},{"number":309,"text":"περιιὼν γὰρ ἀπὸ τοῦ τείχους αἰαὶ πάλιν τῇ πόλει καὶ τῷ λαῷ καὶ τῷ ναῷ διαπρύσιον ἐβόα, ὡς δὲ τελευταῖον προσέθηκεν αἰαὶ δὲ κἀμοί, λίθος ἐκ τοῦ πετροβόλου σχασθεὶς καὶ πλήξας αὐτὸν παραχρῆμα κτείνει, φθεγγομένην δʼ ἔτι τὰς κλῃδόνας ἐκείνας τὴν ψυχὴν ἀφῆκε."},{"number":310,"text":"Ταῦτά τις ἐννοῶν εὑρήσει τὸν μὲν θεὸν ἀνθρώπων κηδόμενον καὶ παντοίως προσημαίνοντα τῷ σφετέρῳ γένει τὰ σωτήρια, τοὺς δʼ ὑπʼ ἀνοίας καὶ κακῶν αὐθαιρέτων ἀπολλυμένους,"},{"number":311,"text":"ὅπου γε Ἰουδαῖοι καὶ τὸ ἱερὸν μετὰ τὴν καθαίρεσιν τῆς Ἀντωνίας τετράγωνον ἐποίησαν, ἀναγεγραμμένον ἐν τοῖς λογίοις ἔχοντες ἁλώσεσθαι τὴν πόλιν καὶ τὸν ναόν, ἐπειδὰν τὸ ἱερὸν γένηται τετράγωνον."},{"number":312,"text":"τὸ δʼ ἐπᾶραν αὐτοὺς μάλιστα πρὸς τὸν πόλεμον ἦν χρησμὸς ἀμφίβολος ὁμοίως ἐν τοῖς ἱεροῖς εὑρημένος γράμμασιν, ὡς κατὰ τὸν καιρὸν ἐκεῖνον ἀπὸ τῆς χώρας αὐτῶν τις ἄρξει τῆς οἰκουμένης."},{"number":313,"text":"τοῦθʼ οἱ μὲν ὡς οἰκεῖον ἐξέλαβον καὶ πολλοὶ τῶν σοφῶν ἐπλανήθησαν περὶ τὴν κρίσιν, ἐδήλου δʼ ἄρα τὴν Οὐεσπασιανοῦ τὸ λόγιον ἡγεμονίαν ἀποδειχθέντος ἐπὶ Ἰουδαίας αὐτοκράτορος."},{"number":314,"text":"ἀλλὰ γὰρ οὐ δυνατὸν ἀνθρώποις τὸ χρεὼν διαφυγεῖν οὐδὲ προορωμένοις."},{"number":315,"text":"οἱ δὲ καὶ τῶν σημείων ἃ μὲν ἔκριναν πρὸς ἡδονὴν ἃ δὲ ἐξουθένησαν, μέχρις οὗ τῇ τε ἁλώσει τῆς πατρίδος καὶ τῷ σφῶν αὐτῶν ὀλέθρῳ διηλέγχθησαν τὴν ἄνοιαν."}],"6":[{"number":316,"text":"Ῥωμαῖοι δὲ τῶν μὲν στασιαστῶν καταπεφευγότων εἰς τὴν πόλιν, καιομένου δὲ αὐτοῦ τε τοῦ ναοῦ καὶ τῶν πέριξ ἁπάντων, κομίσαντες τὰς σημαίας εἰς τὸ ἱερὸν καὶ θέμενοι τῆς ἀνατολικῆς πύλης ἄντικρυς ἔθυσάν τε αὐταῖς αὐτόθι καὶ τὸν Τίτον μετὰ μεγίστων εὐφημιῶν ἀπέφηναν αὐτοκράτορα."},{"number":317,"text":"ταῖς δὲ ἁρπαγαῖς οὕτως ἐνεπλήσθησαν οἱ στρατιῶται πάντες, ὥστε κατὰ τὴν Συρίαν πρὸς ἥμισυ τῆς πάλαι τιμῆς τὸν σταθμὸν τοῦ χρυσίου πιπράσκεσθαι."},{"number":318,"text":"τῶν δʼ ἀνὰ τὸν τοῖχον τοῦ ναοῦ ἱερέων διακαρτερούντων παῖς διψήσας ἱκέτευε τοὺς φύλακας τῶν Ῥωμαίων δοῦναι δεξιὰν αὐτῷ καὶ τὸ δίψος ἐξωμολογεῖτο."},{"number":319,"text":"τῶν δὲ τῆς ἡλικίας καὶ τῆς ἀνάγκης οἶκτον λαβόντων καὶ δόντων δεξιὰς καταβὰς αὐτός τε πίνει καὶ ὃ φέρων ἧκεν ἀγγεῖον πλήσας ὕδατος ᾤχετο φεύγων ἄνω πρὸς τοὺς σφετέρους."},{"number":320,"text":"τῶν δὲ φυλάκων καταλαβεῖν μὲν οὐδεὶς ἴσχυσε, πρὸς δὲ τὴν ἀπιστίαν ἐβλασφήμουν. κἀκεῖνος οὐδὲν ἔφη παραβεβηκέναι τῶν συνθηκῶν· λαβεῖν γὰρ δεξιὰν οὐ τοῦ μένειν παρʼ αὐτοῖς ἀλλὰ τοῦ καταβῆναι μόνον καὶ λαβεῖν ὕδωρ, ἅπερ ἀμφότερα πεποιηκὼς πιστὸς ἔδοξεν εἶναι."},{"number":321,"text":"τὸ μὲν δὴ πανούργημα διὰ τὴν ἡλικίαν μάλιστα τοῦ παιδὸς ἀπεθαύμαζον οἱ πλανηθέντες· πέμπτῃ δʼ ἡμέρᾳ λιμώττοντες οἱ ἱερεῖς καταβαίνουσι καὶ πρὸς Τίτον ἀναχθέντες ὑπὸ τῶν φυλάκων ἱκέτευον τυχεῖν σωτηρίας."},{"number":322,"text":"ὁ δὲ τὸν μὲν τῆς συγγνώμης καιρὸν αὐτοῖς παρῳχηκέναι φήσας, οἴχεσθαι δὲ διʼ ὃν εὐλόγως ἂν αὐτοὺς ἔσωζε, πρέπειν δὲ τοῖς ἱερεῦσι τῷ ναῷ συναπολέσθαι, κελεύει κολάσαι τοὺς ἄνδρας."},{"number":323,"text":"Οἱ δὲ περὶ τοὺς τυράννους ὡς τῷ τε πολέμῳ πάντοθεν ἐκρατοῦντο καὶ περιτετειχισμένοις διαφυγεῖν οὐδαμόθεν ἦν, προκαλοῦνται τὸν Τίτον εἰς λόγους."},{"number":324,"text":"ὁ δὲ καὶ διὰ τὸ φιλάνθρωπον φύσει τὸ γοῦν ἄστυ περισῶσαι προαιρούμενος καὶ τῶν φίλων ἐναγόντων, ἤδη γὰρ μετριάζειν τοὺς λῃστὰς ὑπελάμβανεν, ἵσταται κατὰ τὸ πρὸς δύσιν μέρος τοῦ ἔξωθεν ἱεροῦ·"},{"number":325,"text":"ταύτῃ γὰρ ὑπὲρ τὸν ξυστὸν ἦσαν πύλαι, καὶ γέφυρα συνάπτουσα τῷ ἱερῷ τὴν ἄνω πόλιν·"},{"number":326,"text":"αὕτη τότε μέση τῶν τυράννων ἦν καὶ τοῦ Καίσαρος. τὸ δὲ πλῆθος ἑκατέροις βύζην ἐφεστήκει, Ἰουδαῖοι μὲν περὶ Σίμωνα καὶ Ἰωάννην μετέωροι συγγνώμης ἐλπίδι, Ῥωμαῖοι δὲ Καίσαρι καραδοκοῦντες αὐτῶν τὴν ἀξίωσιν."},{"number":327,"text":"παραγγείλας δὲ τοῖς στρατιώταις Τίτος θυμοῦ τε καὶ βελῶν μένειν ἐγκρατεῖς, καὶ τὸν ἑρμηνέα παραστησάμενος, ὅπερ ἦν τεκμήριον τοῦ κρατεῖν, πρῶτος ἤρξατο λέγειν·"},{"number":328,"text":"ἆρά γε ἤδη κεκόρεσθε τῶν τῆς πατρίδος κακῶν, ὦ ἄνδρες, οἱ μήτε τῆς ἡμετέρας δυνάμεως μήτε τῆς ἑαυτῶν ἀσθενείας ἔννοιαν λαβόντες, ὁρμῇ δὲ ἀσκέπτῳ καὶ μανίᾳ τόν τε δῆμον καὶ τὴν πόλιν καὶ τὸν ναὸν ἀπολωλεκότες,"},{"number":329,"text":"ἀπολούμενοι δὲ καὶ αὐτοὶ δικαίως, οἳ πρῶτον μὲν ἀφʼ οὗ Πομπήιος εἷλεν ὑμᾶς κατὰ κράτος οὐκ ἐπαύσασθε νεωτεροποιίας, ἔπειτα καὶ φανερὸν ἐξηνέγκατε πρὸς Ῥωμαίους πόλεμον;"},{"number":330,"text":"ἆρά γε πλήθει πεποιθότες; καὶ μὴν ἐλάχιστον ὑμῖν μέρος ἀντήρκεσεν τοῦ Ῥωμαίων στρατιωτικοῦ. πίστει τοιγαροῦν συμμάχων; καὶ τί τῶν ἔξω τῆς ἡμετέρας ἡγεμονίας ἐθνῶν ἔμελλεν αἱρήσεσθαι Ἰουδαίους πρὸ Ῥωμαίων;"},{"number":331,"text":"ἀλλʼ ἀλκῇ σωμάτων; καὶ μὴν ἴστε Γερμανοὺς δουλεύοντας ἡμῖν. ὀχυρότητι δὲ τειχῶν; καὶ τί μεῖζον ὠκεανοῦ τεῖχος κώλυμα, ὃν περιβεβλημένοι Βρεττανοὶ τὰ Ῥωμαίων ὅπλα προσκυνοῦσιν;"},{"number":332,"text":"καρτερίᾳ ψυχῆς καὶ πανουργίᾳ στρατηγῶν; ἀλλὰ μὴν ᾔδειτε καὶ Καρχηδονίους ἁλόντας."},{"number":333,"text":"τοιγαροῦν ὑμᾶς ἐπήγειρε κατὰ Ῥωμαίων ἡ Ῥωμαίων φιλανθρωπία, οἳ πρῶτον μὲν ὑμῖν τήν τε χώραν ἔδομεν νέμεσθαι καὶ βασιλεῖς ὁμοφύλους ἐπεστήσαμεν,"},{"number":334,"text":"ἔπειτα τοὺς πατρίους νόμους ἐτηρήσαμεν, καὶ ζῆν οὐ μόνον καθʼ ἑαυτοὺς ἀλλὰ καὶ πρὸς τοὺς ἄλλους ἐπετρέψαμεν ὡς ἐβούλεσθε·"},{"number":335,"text":"τὸ δὲ μέγιστον, δασμολογεῖν τε ὑμῖν ἐπὶ τῷ θεῷ καὶ ἀναθήματα συλλέγειν ἐπετρέψαμεν, καὶ τοὺς ταῦτα φέροντας οὔτε ἐνουθετήσαμεν οὔτε ἐκωλύσαμεν, ἵνʼ ἡμῖν γένησθε πλουσιώτεροι καὶ παρασκευάσησθε τοῖς ἡμετέροις χρήμασιν καθʼ ἡμῶν."},{"number":336,"text":"ἔπειτα τηλικούτων ἀγαθῶν ἀπολαύοντες ἐπὶ τοὺς παρασχόντας ἠνέγκατε τὸν κόρον καὶ δίκην τῶν ἀτιθασεύτων ἑρπετῶν τοῖς σαίνουσι τὸν ἰὸν ἐναφήκατε."},{"number":337,"text":"ἔστω γοῦν, κατεφρονήσατε τῆς Νέρωνος ῥᾳθυμίας, καὶ καθάπερ ῥήγματα ἢ σπάσματα τὸν ἄλλον χρόνον κακοήθως ἠρεμοῦντες ἐν τῇ μείζονι νόσῳ διεφάνητε καὶ πρὸς ἐλπίδας ἀναιδεῖς ἀμέτρους ἐξετείνατε τὰς ἐπιθυμίας."},{"number":338,"text":"ἧκεν ὁ πατὴρ οὑμὸς εἰς τὴν χώραν, οὐ τιμωρησόμενος ὑμᾶς τῶν κατὰ Κέστιον, ἀλλὰ νουθετήσων·"},{"number":339,"text":"δέον γοῦν, εἴπερ ἐπʼ ἀναστάσει τοῦ ἔθνους παρῆν, ἐπὶ τὴν ῥίζαν ὑμῶν δραμεῖν καὶ ταύτην ἐκπορθεῖν τὴν πόλιν εὐθέως, ὁ δὲ Γαλιλαίαν ἐδῄου καὶ τὰ πέριξ ἐπιδιδοὺς ὑμῖν χρόνον εἰς μεταμέλειαν."},{"number":340,"text":"ἀλλʼ ὑμῖν ἀσθένεια τὸ φιλάνθρωπον ἐδόκει κἀκ τῆς ἡμετέρας πρᾳότητος τὴν τόλμαν ἐπεθρέψατε."},{"number":341,"text":"Νέρωνος οἰχομένου τοῦθʼ ὅπερ ἐχρῆν τοὺς πονηροτάτους ἐποιήσατε, ταῖς ἐμφυλίοις ἡμῶν ταραχαῖς ἐπεθαρρήσατε καὶ χωρισθέντων εἰς τὴν Αἴγυπτον ἐμοῦ τε καὶ τοῦ πατρὸς εἰς παρασκευὰς τοῦ πολέμου κατεχρήσασθε τοῖς καιροῖς, καὶ οὐκ ᾐδέσθητε ταράσσειν αὐτοκράτορας γεγενημένους οὓς καὶ στρατηγοὺς φιλανθρώπους ἐπειράσατε."},{"number":342,"text":"προσφυγούσης γοῦν ἡμῖν τῆς ἡγεμονίας, καὶ τῶν μὲν κατὰ ταύτην ἠρεμούντων πάντων, πρεσβευομένων δὲ καὶ συνηδομένων τῶν ἔξωθεν ἐθνῶν, πάλιν οἱ Ἰουδαῖοι πολέμιοι,"},{"number":343,"text":"καὶ πρεσβεῖαι μὲν ὑμῶν πρὸς τοὺς ὑπὲρ Εὐφράτην ἐπὶ νεωτερισμῷ, περίβολοι δὲ τειχῶν ἀνοικοδομούμενοι καινοί, στάσεις δὲ καὶ τυράννων φιλονεικίαι καὶ πόλεμος ἐμφύλιος, μόνα τοῖς οὕτω πονηροῖς πρέποντα."},{"number":344,"text":"ἧκον ἐπὶ τὴν πόλιν ἐγὼ παρὰ τοῦ πατρὸς ἄκοντος λαβὼν σκυθρωπὰ παραγγέλματα. τὸν δῆμον ἀκούσας εἰρηνικὰ φρονεῖν ἥσθην."},{"number":345,"text":"ὑμᾶς παύσασθαι πρὸ πολέμου παρεκάλουν, μέχρι πολλοῦ πολεμούντων ἐφειδόμην, δεξιὰς αὐτομόλοις ἔδωκα, καταφυγοῦσι πίστεις ἐτήρησα, πολλοὺς αἰχμαλώτους ἠλέησα, τοὺς ἐπείγοντας βασανίσας ἐκόλασα; τείχεσιν ὑμετέροις μηχανὰς ἄκων προσήγαγον, ἀεὶ φονῶντας τοὺς στρατιώτας ἐφʼ ὑμῖν κατέσχον, καθʼ ἑκάστην νίκην ὡς ἡττώμενος ὑμᾶς εἰς εἰρήνην προυκαλεσάμην."},{"number":346,"text":"τοῦ ἱεροῦ πλησίον γενόμενος πάλιν ἑκὼν ἐξελαθόμην τῶν τοῦ πολέμου νόμων, φείσασθαι δὲ παρεκάλουν τῶν ἰδίων ὑμᾶς ἁγίων καὶ σῶσαι τὸν ναὸν ἑαυτοῖς, διδοὺς ἄδειάν τε ἐξόδου καὶ πίστιν σωτηρίας, εἰ δʼ ἐβούλεσθε, καὶ μάχης καιρὸν ἐν ἄλλῳ τόπῳ·"},{"number":347,"text":"πάντων ὑπερείδετε καὶ τὸν ναὸν ἰδίαις χερσὶν ἐνεπρήσατε. ἔπειτα, μιαρώτατοι, προκαλεῖσθέ με πρὸς λόγους νῦν; ἵνα τί σώσητε τοιοῦτον οἷον ἀπόλωλεν; ποίας ὑμᾶς αὐτοὺς ἀξιοῦτε μετὰ τὸν ναὸν σωτηρίας;"},{"number":348,"text":"ἀλλὰ καὶ νῦν μετὰ τῶν ὅπλων ἑστήκατε καὶ οὐδʼ ἐν ἐσχάτοις ὑποκρίνεσθε γοῦν ἱκέτας, ὦ ταλαίπωροι, τίνι πεποιθότες;"},{"number":349,"text":"οὐ νεκρὸς μὲν ὑμῶν ὁ δῆμος, οἴχεται δʼ ὁ ναός, ὑπʼ ἐμοὶ δὲ ἡ πόλις, ἐν χερσὶ δὲ ταῖς ἐμαῖς ἔχετε τὰς ψυχάς; εἶτα ὑπολαμβάνετε δόξαν ἀνδρείας τὸ δυσθανατᾶν;"},{"number":350,"text":"οὐ μὴν ἐγὼ φιλονεικήσω πρὸς τὴν ἀπόνοιαν ὑμῶν, ῥίψασι δὲ τὰ ὅπλα καὶ παραδοῦσι τὰ σώματα χαρίζομαι τὸ ζῆν, ὥσπερ ἐν οἰκίᾳ πρᾷος δεσπότης τὰ μὲν ἀνήκεστα κολάσας, τὰ δὲ λοιπὰ σώζων ἐμαυτῷ."},{"number":351,"text":"Πρὸς ταῦτα ἀποκρίνονται δεξιὰν μὲν μὴ δύνασθαι παρʼ αὐτοῦ λαβεῖν, ὀμωμοκέναι γὰρ μήποτε τοῦτο ποιήσειν, ἔξοδον δʼ ᾐτοῦντο διὰ τοῦ περιτειχίσματος μετὰ γυναικῶν καὶ τέκνων· ἀπελεύσεσθαι γὰρ εἰς τὴν ἔρημον καὶ καταλείψειν αὐτῷ τὴν πόλιν."},{"number":352,"text":"πρὸς ταῦτα ἀγανακτήσας Τίτος, εἰ τύχην ἑαλωκότων ἔχοντες αἱρέσεις αὐτῷ προτείνουσι νενικηκότων, κηρῦξαι μὲν ἐκέλευσεν εἰς αὐτοὺς μήτε αὐτομολεῖν ἔτι μήτε δεξιὰν ἐλπίζειν, φείσεσθαι γὰρ οὐδενός,"},{"number":353,"text":"ἀλλὰ πάσῃ δυνάμει μάχεσθαι καὶ σώζειν ἑαυτοὺς ὅπως ἂν δύνωνται· πάντα γὰρ αὐτὸς ἤδη πράξειν πολέμου νόμῳ· τοῖς δὲ στρατιώταις ἐμπιπράναι καὶ διαρπάζειν ἐπέτρεψεν τὴν πόλιν."},{"number":354,"text":"οἱ δὲ ἐκείνην μὲν ἐπέσχον τὴν ἡμέραν, τῇ δὲ ὑστεραίᾳ τό τε ἀρχεῖον καὶ τὴν ἄκραν καὶ τὸ βουλευτήριον καὶ τὸν Ὀφλᾶν καλούμενον ὑφῆψαν·"},{"number":355,"text":"καὶ προύκοψε τὸ πῦρ μέχρι τῶν Ἑλένης βασιλείων, ἃ δὴ κατὰ μέσην τὴν ἄκραν ἦν, ἐκαίοντο δὲ οἱ στενωποὶ καὶ αἱ οἰκίαι νεκρῶν ὑπὸ τοῦ λιμοῦ διεφθαρμένων πλήρεις."},{"number":356,"text":"Κατὰ ταύτην τὴν ἡμέραν οἵ τε Ἰζάτου βασιλέως υἱοὶ καὶ ἀδελφοί, πρὸς οἷς πολλοὶ τῶν ἐπισήμων δημοτῶν ἐκεῖ συνελθόντες, ἱκέτευσαν Καίσαρα δοῦναι δεξιὰν αὐτοῖς. ὁ δὲ καίτοι πρὸς πάντας τοὺς ὑπολοίπους διωργισμένος οὐκ ἤλλαξε τὸ ἦθος, δέχεται δὲ τοὺς ἄνδρας."},{"number":357,"text":"καὶ τότε μὲν ἐν φρουρᾷ πάντας εἶχε, τοὺς δὲ τοῦ βασιλέως παῖδας καὶ συγγενεῖς δήσας ὕστερον εἰς Ῥώμην ἀνήγαγεν πίστιν ὁμήρων παρέξοντας."}],"7":[{"number":358,"text":"Οἱ στασιασταὶ δὲ ἐπὶ τὴν βασιλικὴν ὁρμήσαντες αὐλήν, εἰς ἣν διʼ ὀχυρότητα πολλοὶ τὰς κτήσεις ἀπέθεντο, τούς τε Ῥωμαίους ἀπʼ αὐτῆς τρέπονται καὶ τὸ συνηθροισμένον αὐτόθι τοῦ δήμου πᾶν φονεύσαντες, ὄντας εἰς ὀκτακισχιλίους καὶ τετρακοσίους, τὰ χρήματα διήρπασαν."},{"number":359,"text":"ἐζώγρησαν δὲ καὶ Ῥωμαίων δύο, τὸν μὲν ἱππέα τὸν δὲ πεζόν, καὶ τὸν μὲν πεζὸν ἀποσφάξαντες εὐθέως ἔσυραν περὶ τὴν πόλιν, ὥσπερ ἑνὶ σώματι πάντας Ῥωμαίους ἀμυνόμενοι,"},{"number":360,"text":"ὁ δὲ ἱππεὺς ὠφέλιμόν τι αὐτοῖς πρὸς σωτηρίαν ὑποθήσεσθαι λέγων ἀνάγεται πρὸς Σίμωνα· παρʼ ᾧ μηδὲν εἰπεῖν ἔχων Ἀρδάλᾳ τινὶ τῶν ἡγεμόνων παραδίδοται κολασθησόμενος."},{"number":361,"text":"ὁ δὲ αὐτοῦ ὀπίσω τὼ χεῖρε δήσας καὶ ταινίᾳ τοὺς ὀφθαλμοὺς ἀντικρὺ τῶν Ῥωμαίων προήγαγεν ὡς καρατομήσων· φθάνει δʼ ἐκεῖνος εἰς τοὺς Ῥωμαίους διαφυγὼν ἐν ὅσῳ τὸ ξίφος ἐσπάσατο ὁ Ἰουδαῖος."},{"number":362,"text":"τοῦτον διαφυγόντα ἐκ τῶν πολεμίων ἀνελεῖν μὲν οὐχ ὑπέμεινεν Τίτος, ἀνάξιον δὲ Ῥωμαίων εἶναι στρατιώτην κρίνας, ὅτι ζῶν ἐλήφθη, τά τε ὅπλα ἀφείλετο καὶ τοῦ τάγματος ἐξέβαλεν, ἅπερ ἦν αἰσχυνομένῳ θανάτου χαλεπώτερα."},{"number":363,"text":"Τῇ δʼ ἑξῆς Ῥωμαῖοι τρεψάμενοι τοὺς λῃστὰς ἐκ τῆς κάτω πόλεως τὰ μέχρι τοῦ Σιλωᾶ [πάντα] ἐνέπρησαν, καὶ τοῦ μὲν ἄστεος ἥδοντο δαπανωμένου, τῶν δʼ ἁρπαγῶν διημάρτανον, ἐπειδὴ πάνθʼ οἱ στασιασταὶ προκενοῦντες ἀνεχώρουν εἰς τὴν ἄνω πόλιν."},{"number":364,"text":"ἦν γὰρ αὐτοῖς μετάνοια μὲν οὐδεμία τῶν κακῶν, ἀλαζονεία δὲ ὡς ἐπʼ ἀγαθοῖς· καιομένην γοῦν ἀφορῶντες τὴν πόλιν ἱλαροῖς τοῖς προσώποις εὔθυμοι προσδέχεσθαι τὴν τελευτὴν ἔλεγον, πεφονευμένου μὲν τοῦ δήμου, κεκαυμένου δὲ τοῦ ναοῦ, φλεγομένου δὲ τοῦ ἄστεος μηδὲν καταλιπόντες τοῖς πολεμίοις."},{"number":365,"text":"οὐ μὴν ὅ γε Ἰώσηπος ἐν ἐσχάτοις ἱκετεύων αὐτοὺς ὑπὲρ τῶν λειψάνων τῆς πόλεως ἔκαμνεν, ἀλλὰ πολλὰ μὲν πρὸς τὴν ὠμότητα καὶ τὴν ἀσέβειαν εἰπών, πολλὰ δὲ συμβουλεύσας πρὸς σωτηρίαν οὐδὲν τοῦ χλευασθῆναι πλέον ἀπηνέγκατο."},{"number":366,"text":"ἐπεὶ δὲ οὔτε παραδοῦναι διὰ τὸν ὅρκον ἑαυτοὺς ὑπέμενον οὔτε πολεμεῖν ἐξ ἴσου Ῥωμαίοις ἔθʼ οἷοί τε ἦσαν ὥσπερ εἱρκτῇ περιειλημμένοι, τό τε τοῦ φονεύειν ἔθος ἐκίνει τὰς δεξιάς, σκιδνάμενοι κατὰ τὰ ἔμπροσθεν τῆς πόλεως τοῖς ἐρειπίοις ὑπελόχων τοὺς αὐτομολεῖν ὡρμημένους."},{"number":367,"text":"ἡλίσκοντο δὲ πολλοί, καὶ πάντας ἀποσφάττοντες, ὑπὸ γὰρ ἐνδείας οὐδὲ φεύγειν ἴσχυον, ἐρρίπτουν αὐτῶν κυσὶ τοὺς νεκρούς."},{"number":368,"text":"ἐδόκει δὲ πᾶς τρόπος ἀπωλείας τοῦ λιμοῦ κουφότερος, ὥστε καὶ Ῥωμαίοις ἀπηλπικότες ἤδη τὸν ἔλεον ὅμως προσέφευγον καὶ φονεύουσι τοῖς στασιασταῖς ἑκόντες ἐνέπιπτον."},{"number":369,"text":"τόπος τʼ ἐπὶ τῆς πόλεως οὐδεὶς γυμνὸς ἦν, ἀλλὰ πᾶς λιμοῦ νεκρὸν εἶχεν ἢ στάσεως [καὶ πεπλήρωτο νεκρῶν ἢ διὰ στάσιν ἢ διὰ λιμὸν ἀπολωλότων]."},{"number":370,"text":"Ἔθαλπε δὲ τούς τε τυράννους καὶ τὸ σὺν αὐτοῖς λῃστρικὸν ἐλπὶς ἐσχάτη περὶ τῶν ὑπονόμων, εἰς οὓς καταφεύγοντες οὐ προσεδόκων ἐρευνηθήσεσθαι, μετὰ δὲ τὴν παντελῆ τῆς πόλεως ἅλωσιν ἀναζευξάντων Ῥωμαίων προελθόντες ἀποδράσεσθαι ἐπεχείρουν."},{"number":371,"text":"τὸ δὲ ἦν ἄρα ὄνειρος αὐτοῖς· οὔτε γὰρ τὸν θεὸν οὔτε Ῥωμαίους λήσειν ἔμελλον."},{"number":372,"text":"τηνικαῦτά γε μὴν τοῖς ὑπογείοις πεποιθότες αὐτοὶ πλείονα τῶν Ῥωμαίων ἐνεπίμπρασαν, καὶ τοὺς ἐκ τῶν καιομένων καταφεύγοντας εἰς τὰς διώρυχας ἔκτεινόν τε ἀνέδην καὶ ἐσύλων καὶ εἴ τινος εὕροιεν τροφὴν ἁρπάζοντες αἵματι πεφυρμένην κατέπινον."},{"number":373,"text":"ἦν δὲ καὶ πρὸς ἀλλήλους ἐν ταῖς ἁρπαγαῖς ἤδη πόλεμος αὐτοῖς, δοκοῦσί τε ἄν μοι μὴ φθασθέντες ὑπὸ τῆς ἁλώσεως διʼ ὑπερβολὴν ὠμότητος γεύσασθαι καὶ τῶν νεκρῶν."}],"8":[{"number":374,"text":"Καῖσαρ δέ, ὡς ἀμήχανον ἦν ἐξελεῖν δίχα χωμάτων τὴν ἄνω πόλιν περίκρημνον οὖσαν, διανέμει τοῖς ἔργοις τὴν δύναμιν Λώου μηνὸς εἰκάδι."},{"number":375,"text":"χαλεπὴ δὲ ἦν τῆς ὕλης ἡ κομιδὴ πάντων, ὡς ἔφην, τῶν περὶ τὴν πόλιν ἐφʼ ἑκατὸν σταδίους ἐψιλωμένων εἰς τὰ πρότερον χώματα."},{"number":376,"text":"τῶν μὲν οὖν τεσσάρων ταγμάτων ἠγείρετο τὰ ἔργα κατὰ τὸ πρὸς δύσιν κλίμα τῆς πόλεως ἀντικρὺ τῆς βασιλικῆς αὐλῆς,"},{"number":377,"text":"τὸ δὲ συμμαχικὸν πλῆθος καὶ ὁ λοιπὸς ὄχλος κατὰ τὸν ξυστὸν ἔχου καὶ τὴν γέφυραν καὶ τὸν Σίμωνος πύργον, ὃν ᾠκοδόμησε πρὸς Ἰωάννην πολεμῶν ἑαυτῷ φρούριον."},{"number":378,"text":"Κατὰ ταύτας τὰς ἡμέρας οἱ τῶν Ἰδουμαίων ἡγεμόνες κρύφα συνελθόντες ἐβουλεύσαντο περὶ παραδόσεως σφῶν αὐτῶν, καὶ πέμψαντες ἄνδρας πέντε πρὸς Τίτον ἱκέτευον δοῦναι δεξιὰν αὐτοῖς."},{"number":379,"text":"ὁ δὲ καὶ τοὺς τυράννους ἐνδώσειν ἐλπίσας ἀποσπασθέντων τῶν Ἰδουμαίων, οἳ πολὺ τοῦ πολέμου μέρος ἦσαν, βραδέως μέν, ἀλλʼ οὖν κατανεύει τε τὴν σωτηρίαν αὐτοῖς καὶ τοὺς ἄνδρας ἀνέπεμψε."},{"number":380,"text":"παρασκευαζομένων δὲ ἀποχωρεῖν αἰσθάνεται Σίμων, καὶ πέντε μὲν τοὺς ἀπελθόντας πρὸς Τίτον εὐθέως ἀναιρεῖ, τοὺς δὲ ἡγεμόνας, ὧν ἐπισημότατος ἦν ὁ τοῦ Σωσᾶ Ἰάκωβος, συλλαβὼν εἵργνυσι·"},{"number":381,"text":"τὸ δὲ πλῆθος τῶν Ἰδουμαίων ἀμηχανοῦν διὰ τὴν ἀφαίρεσιν τῶν ἡγεμόνων οὐκ ἀφύλακτον εἶχε καὶ τὸ τεῖχος φρουραῖς ἐπιμελεστέραις διελάμβανεν."},{"number":382,"text":"οὐ μὴν ἀντέχειν οἱ φρουροὶ πρὸς τὰς αὐτομολίας ἴσχυον, ἀλλὰ καίτοι πλείστων φονευομένων πολὺ πλείους οἱ διαφεύγοντες ἦσαν."},{"number":383,"text":"ἐδέχοντο δὲ Ῥωμαῖοι πάντας, τοῦ τε Τίτου διὰ πρᾳότητα τῶν προτέρων ἀμελήσαντος παραγγελμάτων, καὶ αὐτοὶ κόρῳ τοῦ κτείνειν ἀπεχόμενοι καὶ κέρδους ἐλπίδι·"},{"number":384,"text":"τοὺς γὰρ δημοτικοὺς καταλιπόντες μόνους τὸν ἄλλον ὄχλον ἐπώλουν σὺν γυναιξὶ καὶ τέκνοις, ἐλαχίστης τιμῆς ἕκαστον πλήθει τε τῶν πιπρασκομένων καὶ ὀλιγότητι τῶν ὠνουμένων."},{"number":385,"text":"καίπερ δὲ προκηρύξας μηδένα μόνον αὐτομολεῖν, ὅπως καὶ τὰς γενεὰς ἐξαγάγοιεν, ὅμως καὶ τούτους ἐδέχετο· ἐπέστησε μέντοι τοὺς διακρινοῦντας ἀπʼ αὐτῶν, εἴ τις εἴη κολάσεως ἄξιος."},{"number":386,"text":"καὶ τῶν μὲν ἀπεμποληθέντων ἄπειρον ἦν τὸ πλῆθος, οἱ δημοτικοὶ δὲ διεσώθησαν ὑπὲρ τετρακισμυρίους, οὓς διαφῆκεν Καῖσαρ ᾗ φίλον ἦν ἑκάστῳ."},{"number":387,"text":"Ἐν δὲ ταῖς αὐταῖς ἡμέραις καὶ τῶν ἱερέων τις Θεβουθεῖ παῖς, Ἰησοῦς ὄνομα, λαβὼν περὶ σωτηρίας ὅρκους παρὰ Καίσαρος ἐφʼ ᾧ παραδώσει τινὰ τῶν ἱερῶν κειμηλίων,"},{"number":388,"text":"ἔξεισι καὶ παραδίδωσιν ἀπὸ τοῦ τοίχου τοῦ ναοῦ λυχνίας δύο τῶν κατὰ τὸν ναὸν κειμένων παραπλησίας τραπέζας τε καὶ κρατῆρας καὶ φιάλας, πάντα ὁλόχρυσα καὶ στιβαρώτατα,"},{"number":389,"text":"παραδίδωσι δὲ καὶ τὰ καταπετάσματα καὶ τὰ ἐνδύματα τῶν ἀρχιερέων σὺν τοῖς λίθοις καὶ πολλὰ τῶν πρὸς τὰς ἱερουργίας σκευῶν ἄλλα."},{"number":390,"text":"συλληφθεὶς δὲ καὶ ὁ γαζοφύλαξ τοῦ ἱεροῦ Φινέας ὄνομα τούς τε χιτῶνας καὶ τὰς ζώνας ὑπέδειξε τῶν ἱερέων πορφύραν τε πολλὴν καὶ κόκκον, ἃ πρὸς τὰς χρείας ἀπέκειτο τοῦ καταπετάσματος, σὺν οἷς κιννάμωμόν τε πολὺ καὶ κασσίαν καὶ πλῆθος ἑτέρων ἀρωμάτων, ἃ συμμίσγοντες ἐθυμίων ὁσημέραι τῷ θεῷ."},{"number":391,"text":"παρεδόθη δὲ ὑπʼ αὐτοῦ πολλὰ καὶ τῶν ἄλλων κειμηλίων κόσμος τε ἱερὸς οὐκ ὀλίγος, ἅπερ αὐτῷ βίᾳ ληφθέντι τὴν τῶν αὐτομόλων συγγνώμην ἔδωκε."},{"number":392,"text":"Συντετελεσμένων δʼ ἤδη καὶ τῶν χωμάτων ἐν ὀκτωκαίδεκα ἡμέραις ἑβδόμῃ Γορπιαίου μηνὸς Ῥωμαῖοι μὲν προσῆγον τὰς μηχανάς, τῶν δὲ στασιαστῶν οἱ μὲν ἀπεγνωκότες ἤδη τὴν πόλιν ἀνεχώρουν τοῦ τείχους εἰς τὴν ἄκραν, οἱ δὲ ἐγκατεδύοντο τοῖς ὑπονόμοις·"},{"number":393,"text":"πολλοὶ δὲ διαστάντες ἠμύνοντο τοὺς προσάγοντας τὰς ἑλεπόλεις. ἐκράτουν δὲ καὶ τούτων Ῥωμαῖοι πλήθει τε καὶ βίᾳ καὶ τὸ μέγιστον, εὐθυμοῦντες ἀθύμων ἤδη καὶ παρειμένων."},{"number":394,"text":"ὡς δὲ παρερράγη μέρος τι τοῦ τείχους, καί τινες τῶν πύργων τυπτόμενοι τοῖς κριοῖς ἐνέδοσαν, φυγὴ μὲν ἦν εὐθέως τῶν ἀμυνομένων, δέος δὲ καὶ τοῖς τυράννοις ἐμπίπτει σφοδρότερον τῆς ἀνάγκης·"},{"number":395,"text":"πρὶν γὰρ ὑπερβῆναι τοὺς πολεμίους ἐνάρκων τε καὶ μετέωροι πρὸς φυγὴν ἦσαν, ἦν δὲ ἰδεῖν τοὺς πάλαι σοβαροὺς καὶ τοῖς ἀσεβήμασιν ἀλαζόνας τότε ταπεινοὺς καὶ τρέμοντας, ὡς ἐλεεινὴν εἶναι καίπερ ἐν πονηροτάτοις τὴν μεταβολήν."},{"number":396,"text":"ὥρμησαν μὲν οὖν ἐπὶ τὸ περιτείχισμα δραμόντες ὤσασθαί τε τοὺς φρουροὺς καὶ διακόψαντες ἐξελθεῖν·"},{"number":397,"text":"ὡς δὲ τοὺς μὲν πάλαι πιστοὺς ἑώρων οὐδαμοῦ, διέφυγον γὰρ ὅπῃ τινὶ συνεβούλευεν ἡ ἀνάγκη, προσθέοντες δὲ οἱ μὲν ὅλον ἀνατετράφθαι τὸ πρὸς δύσιν τεῖχος ἤγγελλον, οἱ δʼ ἐμβεβληκέναι τοὺς Ῥωμαίους ἤδη τε πλησίον εἶναι ζητοῦντας αὐτούς,"},{"number":398,"text":"ἕτεροι δὲ καὶ ἀφορᾶν ἀπὸ τῶν πύργων πολεμίους ἔλεγον πλάζοντος τὰς ὄψεις τοῦ δέους, ἐπὶ στόμα πεσόντες ἀνῴμωζον τὴν ἑαυτῶν φρενοβλάβειαν καὶ καθάπερ ὑποκεκομμένοι τὰ νεῦρα τῆς φυγῆς ἠπόρουν."},{"number":399,"text":"ἔνθα δὴ μάλιστʼ ἄν τις καταμάθοι τήν τε τοῦ θεοῦ δύναμιν ἐπὶ τοῖς ἀνοσίοις καὶ τὴν Ῥωμαίων τύχην· οἱ μέν γε τύραννοι τῆς ἀσφαλείας ἐγύμνωσαν αὑτοὺς κἀκ τῶν πύργων κατέβησαν ἑκόντες, ἐφʼ ὧν βίᾳ μὲν οὐδέποθʼ ἁλῶναι, μόνῳ δʼ ἐδύναντο λιμῷ."},{"number":400,"text":"Ῥωμαῖοι δὲ τοσαῦτα περὶ τοῖς ἀσθενεστέροις τείχεσι καμόντες παρέλαβον τύχῃ τὰ μὴ δυνατὰ τοῖς ὀργάνοις· παντὸς γὰρ ἰσχυρότεροι μηχανήματος ἦσαν οἱ τρεῖς πύργοι, περὶ ὧν ἀνωτέρω δεδηλώκαμεν."},{"number":401,"text":"Καταλιπόντες δὴ τούτους, μᾶλλον δὲ ὑπὸ τοῦ θεοῦ καταβληθέντες ἀπʼ αὐτῶν, παραχρῆμα μὲν εἰς τὴν ὑπὸ τῇ Σιλωᾶ φάραγγα καταφεύγουσιν, αὖθις δὲ ὀλίγον ἀνακύψαντες ἐκ τοῦ δέους ὥρμησαν ἐπὶ τὸ τῇδε περιτείχισμα."},{"number":402,"text":"χρησάμενοι δὲ ταῖς τόλμαις ἀγενεστέραις τῆς ἀνάγκης, κατεάγησαν γὰρ ἤδη τὴν ἰσχὺν ἅμα τῷ δέει καὶ ταῖς συμφοραῖς, ὑπὸ τῶν φρουρῶν ἀνωθοῦνται καὶ σκεδασθέντες ὑπʼ ἀλλήλων κατέδυσαν εἰς τοὺς ὑπονόμους."},{"number":403,"text":"Ῥωμαῖοι δὲ τῶν τειχῶν κρατήσαντες τάς τε σημαίας ἔστησαν ἐπὶ τῶν πύργων καὶ μετὰ κρότου καὶ χαρᾶς ἐπαιάνιζον ἐπὶ τῇ νίκῃ, πολὺ τῆς ἀρχῆς κουφότερον τοῦ πολέμου τὸ τέλος εὑρηκότες· ἀναιμωτὶ γοῦν τοῦ τελευταίου τείχους ἐπιβάντες ἠπίστουν, καὶ μηδένα βλέποντες ἀντίπαλον ἀληθῶς ἠπόρηντο."},{"number":404,"text":"εἰσχυθέντες δὲ τοῖς στενωποῖς ξιφήρεις τούς τε καταλαμβανομένους ἐφόνευον ἀνέδην καὶ τῶν συμφευγόντων τὰς οἰκίας αὐτάνδρους ὑπεπίμπρασαν."},{"number":405,"text":"πολλὰς δὲ κεραΐζοντες ὁπότʼ ἔνδον παρέλθοιεν ἐφʼ ἁρπαγήν, γενεὰς ὅλας νεκρῶν κατελάμβανον καὶ τὰ δωμάτια πλήρη τῶν τοῦ λιμοῦ πτωμάτων, ἔπειτα πρὸς τὴν ὄψιν πεφρικότες κεναῖς χερσὶν ἐξῄεσαν."},{"number":406,"text":"οὐ μὴν οἰκτείροντες τοὺς οὕτως ἀπολωλότας ταὐτὸ καὶ πρὸς τοὺς ζῶντας ἔπασχον, ἀλλὰ τὸν ἐντυγχάνοντα διελαύνοντες ἀπέφραξαν μὲν τοὺς στενωποὺς νεκροῖς, αἵματι δὲ ὅλην τὴν πόλιν κατέκλυσαν, ὡς πολλὰ καὶ τῶν φλεγομένων σβεσθῆναι τῷ φόνῳ."},{"number":407,"text":"καὶ οἱ μὲν κτείνοντες ἐπαύσαντο πρὸς ἑσπέραν, ἐν δὲ τῇ νυκτὶ τὸ πῦρ ἐπεκράτει, φλεγομένοις δʼ ἐπανέτειλεν Ἱεροσολύμοις ἡμέρα Γορπιαίου μηνὸς ὀγδόη,"},{"number":408,"text":"πόλει τοσαύταις χρησαμένῃ συμφοραῖς κατὰ τὴν πολιορκίαν, ὅσοις ἀπὸ κτίσεως ἀγαθοῖς κεχρημένη πάντως ἂν ἐπίφθονος ἔδοξεν, οὐ μὴν ἀξίᾳ κατʼ ἄλλο τι τῶν τηλικούτων ἀτυχημάτων ἢ τὸ γενεὰν τοιαύτην ἐνεγκεῖν, ὑφʼ ἧς ἀνετράπη."}],"9":[{"number":409,"text":"Παρελθὼν δὲ Τίτος εἴσω τά τε ἄλλα τῆς ὀχυρότητος τὴν πόλιν καὶ τῶν πύργων ἀπεθαύμασεν, οὓς οἱ τύραννοι κατὰ φρενοβλάβειαν ἀπέλιπον."},{"number":410,"text":"κατιδὼν γοῦν τό τε ναστὸν αὐτῶν ὕψος καὶ τὸ μέγεθος ἑκάστης πέτρας τήν τε ἀκρίβειαν τῆς ἁρμονίας, καὶ ὅσοι μὲν εὖρος ἡλίκοι δὲ ἦσαν τὴν ἀνάστασιν,"},{"number":411,"text":"σὺν θεῷ γε ἐπολεμήσαμεν, ἔφη, καὶ θεὸς ἦν ὁ τῶνδε τῶν ἐρυμάτων Ἰουδαίους καθελών, ἐπεὶ χεῖρες ἀνθρώπων ἢ μηχαναὶ τί πρὸς τούτους τοὺς πύργους δύνανται;"},{"number":412,"text":"τότε μὲν οὖν πολλὰ τοιαῦτα διελέχθη πρὸς τοὺς φίλους, τοὺς δὲ τῶν τυράννων δεσμώτας, ὅσοι κατελήφθησαν ἐν τοῖς φρουρίοις, ἀνῆκεν."},{"number":413,"text":"αὖθις δὲ τὴν ἄλλην ἀφανίζων πόλιν καὶ τὰ τείχη κατασκάπτων τούτους τοὺς πύργους κατέλιπε μνημεῖον εἶναι τῆς αὐτοῦ τύχης, ᾗ συστρατιώτιδι χρησάμενος ἐκράτησε τῶν ἁλῶναι μὴ δυναμένων."},{"number":414,"text":"Ἐπεὶ δʼ οἱ στρατιῶται μὲν ἔκαμνον ἤδη φονεύοντες, πολὺ δέ τι πλῆθος τῶν περιόντων ἀνεφαίνετο, κελεύει Καῖσαρ μόνους μὲν τοὺς ἐνόπλους καὶ χεῖρας ἀντίσχοντας κτείνειν, τὸ δὲ λοιπὸν πλῆθος ζωγρεῖν."},{"number":415,"text":"οἱ δὲ μετὰ τῶν παρηγγελμένων τό τε γηραιὸν καὶ τοὺς ἀσθενεῖς ἀνῄρουν, τὸ δʼ ἀκμάζον καὶ χρήσιμον εἰς τὸ ἱερὸν συνελάσαντες ἐγκατέκλεισαν τῷ τῶν γυναικῶν περιτειχίσματι."},{"number":416,"text":"καὶ φρουρὸν μὲν ἐπέστησε Καῖσαρ ἕνα τῶν ἀπελευθέρων, Φρόντωνα δὲ τῶν φίλων ἐπικρινοῦντα τὴν ἀξίαν ἑκάστῳ τύχην."},{"number":417,"text":"ὁ δὲ τοὺς μὲν στασιώδεις καὶ λῃστρικοὺς πάντας ὑπʼ ἀλλήλων ἐνδεικνυμένους ἀπέκτεινε, τῶν δὲ νέων τοὺς ὑψηλοτάτους καὶ καλοὺς ἐπιλέξας ἐτήρει τῷ θριάμβῳ."},{"number":418,"text":"τοῦ δὲ λοιποῦ πλήθους τοὺς ὑπὲρ ἑπτακαίδεκα ἔτη δήσας ἔπεμψεν εἰς τὰ κατʼ Αἴγυπτον ἔργα, πλείστους δʼ εἰς τὰς ἐπαρχίας διεδωρήσατο Τίτος φθαρησομένους ἐν τοῖς θεάτροις σιδήρῳ καὶ θηρίοις· οἱ δʼ ἐντὸς ἑπτακαίδεκα ἐτῶν ἐπράθησαν."},{"number":419,"text":"ἐφθάρησαν δὲ αὐτῶν ἐν αἷς διέκρινεν ὁ Φρόντων ἡμέραις ὑπʼ ἐνδείας χίλιοι πρὸς τοῖς μυρίοις, οἱ μὲν ὑπὸ μίσους τῶν φυλάκων μὴ μεταλαμβάνοντες τροφῆς, οἱ δʼ οὐ προσιέμενοι διδομένην· πρὸς δὲ τὸ πλῆθος ἦν ἔνδεια καὶ σίτου."},{"number":420,"text":"Τῶν μὲν οὖν αἰχμαλώτων πάντων, ὅσα καθʼ ὅλον ἐλήφθη τὸν πόλεμον, ἀριθμὸς ἐννέα μυριάδες καὶ ἑπτακισχίλιοι συνήχθη, τῶν δὲ ἀπολομένων κατὰ πᾶσαν τὴν πολιορκίαν μυριάδες ἑκατὸν καὶ δέκα."},{"number":421,"text":"τούτων τὸ πλέον ὁμόφυλον μὲν ἀλλʼ οὐκ ἐπιχώριον· ἀπὸ γὰρ τῆς χώρας ὅλης ἐπὶ τὴν τῶν ἀζύμων ἑορτὴν συνεληλυθότες ἐξαπίνης τῷ πολέμῳ περιεσχέθησαν, ὥστε τὸ μὲν πρῶτον αὐτοῖς τὴν στενοχωρίαν γενέσθαι λοιμώδη φθοράν, αὖθις δὲ καὶ λιμὸν ὠκύτερον."},{"number":422,"text":"ὅτι δʼ ἐχώρει τοσούτους ἡ πόλις, δῆλον ἐκ τῶν ἐπὶ Κεστίου συναριθμηθέντων, ὃς τὴν ἀκμὴν τῆς πόλεως διαδηλῶσαι Νέρωνι βουλόμενος καταφρονοῦντι τοῦ ἔθνους παρεκάλεσεν τοὺς ἀρχιερεῖς, εἴ πως δυνατὸν εἴη τὴν πληθὺν ἐξαριθμήσασθαι·"},{"number":423,"text":"οἱ δʼ ἐνστάσης ἑορτῆς, πάσχα καλεῖται, καθʼ ἣν θύουσιν μὲν ἀπὸ ἐνάτης ὥρας μέχρις ἑνδεκάτης, ὥσπερ δὲ φατρία περὶ ἑκάστην γίνεται θυσίαν οὐκ ἐλάσσων ἀνδρῶν δέκα, μόνον γὰρ οὐκ ἔξεστιν δαίνυσθαι, πολλοὶ δὲ καὶ συνείκοσιν ἀθροίζονται,"},{"number":424,"text":"τῶν μὲν θυμάτων εἰκοσιπέντε μυριάδας ἠρίθμησαν, πρὸς δὲ πεντακισχίλια ἑξακόσια."},{"number":425,"text":"γίνονται ἀνδρῶν, ἵνʼ ἑκάστου δέκα δαιτυμόνας θῶμεν, μυριάδες ἑβδομήκοντα καὶ διακόσιαι καθαρῶν ἁπάντων καὶ ἁγίων·"},{"number":426,"text":"οὔτε γὰρ λεπροῖς οὔτε γονορροιϊκοῖς οὔτε γυναιξὶν ἐπεμμήνοις οὔτε τοῖς ἄλλως μεμιασμένοις ἐξὸν ἦν τῆσδε τῆς θυσίας μεταλαμβάνειν,"},{"number":427,"text":"ἀλλʼ οὐδὲ τοῖς ἀλλοφύλοις, ὅσοι κατὰ θρησκείαν παρῆσαν, πολὺ δὲ τούτων πλῆθος ἔξωθεν συλλέγεται."},{"number":428,"text":"τότε γε μὴν ὥσπερ εἰς εἱρκτὴν ὑπὸ τῆς εἱμαρμένης πᾶν συνεκλείσθη τὸ ἔθνος, καὶ ναστὴν ὁ πόλεμος τὴν πόλιν ἀνδρῶν ἐκυκλώσατο."},{"number":429,"text":"πᾶσαν γοῦν ἀνθρωπίνην καὶ δαιμονίαν φθορὰν ὑπερβάλλει τὸ πλῆθος τῶν ἀπολωλότων· ἐπεὶ γοῦν τῶν φανερῶν οὓς μὲν ἀνεῖλον οὓς δʼ ᾐχμαλωτίσαντο Ῥωμαῖοι, τοὺς ἐν τοῖς ὑπονόμοις ἀνηρεύνων καὶ τοὔδαφος ἀναῤῥηγνύντες ὅσοις μὲν ἐνετύγχανον ἔκτεινον,"},{"number":430,"text":"εὑρέθησαν δὲ κἀκεῖ νεκροὶ πλείους δισχιλίων, οἱ μὲν ὑπὸ σφῶν αὐτῶν οἱ δὲ ὑπʼ ἀλλήλων, τὸ πλέον δʼ ὑπὸ τοῦ λιμοῦ διεφθαρμένοι."},{"number":431,"text":"δεινὴ δʼ ὑπήντα τοῖς ἐπεισπίπτουσιν ὀδμὴ τῶν σωμάτων, ὡς πολλοὺς μὲν ἀναχωρεῖν εὐθέως, τοὺς δὲ ὑπὸ πλεονεξίας εἰσδύεσθαι νεκροὺς σεσωρευμένους ἐμπατοῦντας·"},{"number":432,"text":"πολλὰ γὰρ τῶν κειμηλίων ἐν ταῖς διώρυξιν εὑρίσκετο, καὶ πᾶσαν θεμιτὴν ὁδὸν ἐποίει τὸ κέρδος· ἀνήγοντο δὲ καὶ δεσμῶται πολλοὶ τῶν τυράννων· οὐδὲ γὰρ ἐν ἐσχάτοις ἐπαύσαντο τῆς ὠμότητος."},{"number":433,"text":"ἀπετίσατό γε μὴν ὁ θεὸς ἀμφοτέρους ἀξίως, καὶ Ἰωάννης μὲν λιμώττων μετὰ τῶν ἀδελφῶν ἐν τοῖς ὑπονόμοις ἣν πολλάκις ὑπερηφάνησε παρὰ Ῥωμαίων δεξιὰν λαβεῖν ἱκέτευσε, Σίμων δὲ πολλὰ διαμαχήσας πρὸς τὴν ἀνάγκην, ὡς διὰ τῶν ἑξῆς δηλώσομεν, αὑτὸν παραδίδωσιν."},{"number":434,"text":"ἐφυλάχθη δὲ ὁ μὲν τῷ θριάμβῳ σφάγιον, ὁ δʼ Ἰωάννης δεσμοῖς αἰωνίοις. Ῥωμαῖοι δὲ τάς τʼ ἐσχατιὰς τοῦ ἄστεος ἐνέπρησαν καὶ τὰ τείχη κατέσκαψαν."}],"10":[{"number":435,"text":"Ἑάλω μὲν οὕτως Ἱεροσόλυμα ἔτει δευτέρῳ τῆς Οὐεσπασιανοῦ ἡγεμονίας Γορπιαίου μηνὸς ὀγδόῃ, ἁλοῦσα δὲ καὶ πρότερον πεντάκις τοῦτο δεύτερον ἠρημώθη."},{"number":436,"text":"Ἀσωχαῖος μὲν γὰρ ὁ τῶν Αἰγυπτίων βασιλεὺς καὶ μετʼ αὐτὸν Ἀντίοχος, ἔπειτα Πομπήιος καὶ ἐπὶ τούτοις σὺν Ἡρώδῃ Σόσσιος ἑλόντες ἐτήρησαν τὴν πόλιν."},{"number":437,"text":"πρὸ δὲ τούτων ὁ τῶν Βαβυλωνίων βασιλεὺς κρατήσας ἠρήμωσεν αὐτὴν μετὰ ἔτη τῆς κτίσεως χίλια τετρακόσια ἑξηκονταοκτὼ μῆνας ἕξ."},{"number":438,"text":"ὁ δὲ πρῶτος κτίσας ἦν Χαναναίων δυνάστης ὁ τῇ πατρίῳ γλώσσῃ κληθεὶς βασιλεὺς δίκαιος· ἦν γὰρ δὴ τοιοῦτος. διὰ τοῦτο ἱεράσατό τε τῷ θεῷ πρῶτος καὶ τὸ ἱερὸν πρῶτος δειμάμενος Ἱεροσόλυμα τὴν πόλιν προσηγόρευσεν Σόλυμα καλουμένην πρότερον."},{"number":439,"text":"τὸν μὲν δὴ τῶν Χαναναίων λαὸν ἐκβαλὼν ὁ τῶν Ἰουδαίων βασιλεὺς Δαυίδης κατοικίζει τὸν ἴδιον, καὶ μετὰ τοῦτον ἔτεσι τετρακοσίοις ἑβδομήκοντα καὶ ἑπτὰ μησὶν ἓξ ὑπὸ Βαβυλωνίων κατασκάπτεται."},{"number":440,"text":"ἀπὸ δὲ Δαυίδου τοῦ βασιλέως, ὃς πρῶτος αὐτῆς ἐβασίλευσεν Ἰουδαῖος, μέχρι τῆς ὑπὸ Τίτου γενομένης κατασκαφῆς ἔτη χίλια καὶ ἑκατὸν ἑβδομήκοντα καὶ ἐννέα."},{"number":441,"text":"ἀπὸ δὲ τῆς πρώτης κτίσεως ἔτη μέχρι τῆς ἐσχάτης ἁλώσεως δισχίλια ἑκατὸν ἑβδομήκοντα καὶ ἑπτά."},{"number":442,"text":"ἀλλὰ γὰρ οὔθʼ ἡ ἀρχαιότης οὔθʼ ὁ πλοῦτος ὁ βαθὺς οὔτε τὸ διαπεφοιτηκὸς ὅλης τῆς οἰκουμένης ἔθνος οὔθʼ ἡ μεγάλη δόξα τῆς θρησκείας ἤρκεσέ τι πρὸς ἀπώλειαν αὐτῇ. τοιοῦτο μὲν δὴ τὸ τέλος τῆς Ἱεροσολύμων πολιορκίας."}]},"count":442};})();